how: [
["在做什麼", "大型雲端業者想要專門跑自家 AI 服務的晶片，不想全部都買通用 GPU，就自己訂規格，請設計服務公司幫忙把晶片做出來。"],
["怎麼運作", "雲端業者提出要的功能與規格；設計服務公司用 EDA 工具，挑選、整合各種矽智財（IP），完成電路設計、驗證與佈局後下線，再幫客戶向晶圓代工廠下單、安排 CoWoS 等先進封裝與測試，最後交貨。"],
["關鍵名詞", "ASIC：為特定用途客製的晶片。矽智財（IP）：別人設計好、可以授權使用的電路積木，例如高速介面、記憶體、處理器核心。NRE：前期設計費用，量產後再收晶片的錢。下線（Tape-out）：設計完成交給晶圓廠。"],
["景氣看什麼", "雲端業者資本支出與自研晶片計畫、新案子何時從設計轉進量產、先進製程與 CoWoS 產能是否到位；單一大客戶占比高，專案換代時營運波動也大。"],
["台灣角色", "台灣有多家設計服務公司緊鄰台積電，擅長把客戶規格落實到先進製程；也有矽智財公司提供記憶體、介面與 RISC-V 處理器 IP，收授權金與權利金。"],
],
trends: [
"雲端業者自研 AI 加速器越來越普遍，設計服務從單顆晶片延伸到整套運算平台",
"晶片改採小晶片（Chiplet）架構，多顆晶粒用先進封裝拼成一顆，整合能力更重要",
"高速 SerDes、HBM 介面等關鍵矽智財成為門檻，授權與權利金收入跟著製程升級",
"RISC-V 開放架構進入資料中心與車用晶片，提供另一種處理器 IP 選擇",
],
