how: [
["在做什麼", "晶片上的接點又小又密，沒辦法直接焊到主機板上，中間需要一片「轉接板」把細線路慢慢放大，這就是 IC 載板；高階運算晶片多用 ABF 載板。"],
["怎麼運作", "以核心板為底，一層層貼上 ABF 絕緣膜、用雷射鑽出微小孔洞、再做化學銅與電鍍出銅線路，重複多次形成多層結構；最後晶片用凸塊接在上面封裝，底部用錫球焊到主機板。"],
["關鍵名詞", "ABF：一種絕緣增層薄膜，適合做很細的線路。BT 載板：另一種載板材料，常用在記憶體與手機晶片。層數與面積：晶片越大、訊號越多，載板就要越大、越多層，良率也越難做。"],
["景氣看什麼", "AI 晶片與伺服器 CPU 出貨、PC 與手機需求、載板新產能開出的速度。高階大尺寸載板供應較緊，一般 PC 用載板則容易受庫存與價格競爭影響。"],
["台灣角色", "台灣是全球 ABF 與 BT 載板的主要供應地之一，欣興、南電、景碩等公司供貨給國際 CPU、GPU 與網通晶片大廠；上游的增層膜與部分材料則多仰賴日本供應。"],
],
trends: [
"AI 晶片封裝越做越大，載板面積與層數同步提高，良率與產能更難做",
"玻璃基板被視為下一代載板材料，平整、耐熱，有機會做出更細的線路",
"高階 ABF 載板與一般 PC 用載板走勢分化，高階大尺寸產品供應較緊",
"增層膜、低膨脹玻纖布等關鍵材料供應集中在少數廠商，容易成為瓶頸",
],
