how: [
["在做什麼", "印刷電路板（PCB）是把所有晶片與零件接在一起的「道路網」。AI 伺服器的主機板、加速卡板、交換器板線路又多又密，層數高、單價也高。"],
["怎麼運作", "先在銅箔基板上蝕刻出內層線路，把好幾層和絕緣膠片疊起來壓合；接著機械鑽孔或雷射打孔、在孔壁電鍍銅讓各層導通，最後做外層線路、防焊漆與表面處理，電測後出貨。"],
["關鍵名詞", "層數：一塊板疊了幾層線路，越多越難做。通孔／盲孔：貫穿整片的孔，或只連到某幾層的小孔。HDI：用雷射打微小孔、線路更細的高密度板。軟板：可以彎折的電路板，多用在手機與穿戴裝置。"],
["景氣看什麼", "AI 伺服器與交換器出貨、平台升級帶動的層數與材料升級、手機與車用需求；另外要留意銅價、銅箔基板價格，以及新廠產能是否順利開出。"],
["台灣角色", "台灣是全球主要 PCB 生產地之一，金像電、健鼎、華通等做伺服器與網通板，臻鼎、台郡等則在手機與軟板領域有一席之地。"],
],
trends: [
"AI 伺服器主機板與加速卡板層數提高、板子變大，每片價值跟著提升",
"交換器傳輸速度提升，帶動高層數網通板與低損耗材料需求",
"高密度互連（HDI）從手機擴大到 AI 加速卡與伺服器模組",
"台廠在泰國等東南亞地區設新廠，回應客戶分散生產地的需求",
],
