how: [
["在做什麼", "晶圓廠要先蓋好超乾淨的無塵室，再搬進上百台設備，生產時還要持續供應化學品、氣體與耗材。這個題材就是替晶圓廠「蓋廠、搬設備、送材料」的公司。"],
["怎麼運作", "廠務工程公司負責無塵室、空調、純水、氣體與化學品管線；天花板的風扇過濾機組把潔淨空氣往下吹，晶圓裝在密封的傳送盒裡，由天車在機台之間搬運；下層支援層放真空泵、氣體櫃、化學品與廢氣處理設備。"],
["關鍵名詞", "無塵室：控制空氣中微粒數量的廠房。晶圓傳送盒（FOUP）：保護晶圓不沾灰塵的密封盒。超純水：清洗晶圓用、幾乎不含雜質的水。濕製程設備：用化學液體清洗、蝕刻晶圓的機台。"],
["景氣看什麼", "晶圓廠的資本支出與新廠時程（廠務工程最早受惠），設備進駐時程，以及量產後的稼動率（耗材需求）；海外建廠也會帶動台灣廠務與設備公司跟著出海。"],
["台灣角色", "台灣有漢唐、亞翔、帆宣等無塵室與廠務統包公司，家登做晶圓與光罩傳送盒，崇越、華立代理材料，弘塑、辛耘做濕製程設備，京鼎做設備模組，跟著台灣晶圓廠在全球擴廠。"],
],
