how: [
["在做什麼", "每顆晶片出貨前都要確認是好的。測試分兩關：還在晶圓上時先測一次，封裝完成後再測一次，把壞的挑掉，避免裝進昂貴的伺服器才發現問題。"],
["怎麼運作", "晶圓測試用「探針卡」上密密麻麻的細針碰觸每顆晶粒的接點，標出壞晶粒；切割封裝後，分類機把 IC 放進「測試座」，經測試板接上測試機跑完整功能；部分晶片還要在高溫下長時間運作，篩掉早期故障品。"],
["關鍵名詞", "探針卡：晶圓測試用、針數很多的客製化介面。測試座（Socket）：成品測試時固定晶片、用彈簧針接觸接點的座子。測試板（Load Board）：連接測試座與測試機的電路板。老化測試（Burn-in）：高溫加壓運作，提早找出不耐用的晶片。"],
["景氣看什麼", "AI 晶片與高階手機晶片的新案數量、晶片尺寸與接點數變化（越大越複雜，測試時間越長、介面越貴）、測試代工廠的機台稼動率與擴產。"],
["台灣角色", "台灣有穎崴（測試座）、旺矽（探針卡）、精測（測試板與探針卡）等測試介面公司，以及京元電子等測試代工廠，就近服務台灣的晶圓代工與 IC 設計客戶。"],
],
trends: [
"AI 晶片面積變大、接點變多，測試時間拉長，測試座與探針卡規格跟著升級",
"小晶片（Chiplet）封裝前要確認每顆晶粒都是好的，晶圓測試的重要性提高",
"系統級測試（SLT）成為新的一關，模擬晶片裝進系統後的實際運作",
"高功耗晶片測試時需要主動溫控，測試座與分類機要能處理散熱",
],
