how: [
["在做什麼", "電容、電阻、電感這些「被動元件」不會自己運算，但每塊電路板都需要它們來穩定電壓、過濾雜訊、限制電流。AI 伺服器功耗高、電路複雜，用量比一般伺服器多很多。"],
["怎麼運作", "以 MLCC（積層陶瓷電容）為例：陶瓷粉做成薄片、印上金屬電極，一層層交錯疊起來（奇數層接左端、偶數層接右端），壓緊切小後高溫燒結，兩端再做端電極，就成為米粒大小的電容。"],
["關鍵零件", "MLCC：最常見的電容，貼在晶片周圍穩定電壓。電感：搭配電源轉換穩定電流。電阻：限制電流。石英元件：像節拍器一樣提供精準時脈。固態電容：容量大、適合電源段。"],
["景氣看什麼", "被動元件常有庫存循環：看通路庫存、稼動率與報價；需求面看 AI 伺服器、車用、手機與 PC。高容值、耐高溫的車用與伺服器規格產品，價格通常比一般品穩定。"],
["台灣角色", "國巨是全球主要的電阻與 MLCC 供應商之一，另有華新科、禾伸堂等電容廠，奇力新、佳邦等電感廠，信昌電做陶瓷粉，以及晶技、加高、台嘉碩等石英元件公司。"],
],
trends: [
"MLCC 往小尺寸、高容值發展，同樣面積要疊更多、更薄的陶瓷層",
"AI 伺服器與車用規格要求耐高溫、高可靠度，產品組合往高階規格移動",
"晶片供電電流變大，電感與電容往晶片背面與封裝內部靠近",
"AI 叢集需要更精準的時脈，高頻、低抖動的石英振盪器需求提高",
],
