how: [
["在做什麼", "雲端業者與 GPU 廠設計好規格後，需要有人把 GPU 模組、主機板、電源、散熱、網路線全部組起來、測好，再整櫃運到機房。台灣代工廠就是全球 AI 伺服器的主要組裝者。"],
["怎麼運作", "先把晶片與零件焊上主機板（L6），再裝成一台完整伺服器並長時間開機測試（L10）；AI 伺服器常進一步把運算托盤、交換器、電源櫃與液冷管路裝進同一個機櫃，整櫃測好後出貨（L11）。"],
["關鍵名詞", "ODM：依客戶需求設計並代工生產。L6／L10／L11：組裝整合的層級，數字越大整合越完整。整櫃出貨：一次交付整個機櫃，客戶到貨插電就能上線。"],
["景氣看什麼", "雲端業者資本支出、GPU 新平台的量產時程與良率、零組件是否缺料；整櫃出貨金額大，但多數成本是 GPU，毛利率通常不高，要看營收規模與費用控制。"],
["台灣角色", "鴻海、廣達、緯創、緯穎、英業達等是全球主要伺服器代工廠，直接服務美國雲端業者與 GPU 廠；技嘉、神達等則以自有品牌與系統產品為主。"],
],
trends: [
"出貨型態由單台伺服器走向整櫃（L11），代工廠要負責液冷、電源與網路的整合測試",
"雲端業者自研 AI 晶片增加，代工廠同時服務 GPU 平台與客製 ASIC 平台",
"為了貼近客戶與分散風險，組裝產能往美國、墨西哥與東南亞擴建",
"整櫃測試時間長、場地與電力需求大，測試能力本身成為競爭門檻",
],
