how: [
["在做什麼", "伺服器需要堅固的鋼板外殼固定主機板、電源和風扇，再裝進機櫃；滑軌讓工程師能像拉抽屜一樣把整台伺服器拉出來維修，不必整台拆下。"],
["怎麼運作", "鋼捲經過沖壓、折彎、CNC 加工與表面處理做成機殼與機櫃；滑軌由三節嵌套的鋼軌和滾珠組成，一節套一節伸出，既要承受很重的伺服器，又要拉得順、鎖得穩。"],
["關鍵零件", "伺服器機殼：依主機板尺寸與散熱設計客製。機櫃：放置多台伺服器的鐵架。滑軌：承重與順暢度是關鍵，AI 伺服器加上液冷後更重，對滑軌強度要求更高。"],
["景氣看什麼", "伺服器出貨量、AI 機櫃比例（更重更大、單價更高）、新平台設計導入；鋼材價格會影響成本，客戶集中度也值得注意。"],
["台灣角色", "川湖是全球主要的伺服器滑軌供應商之一，南俊國際也做滑軌；勤誠、營邦、迎廣等做伺服器機殼與機櫃，多直接供貨給雲端業者或伺服器代工廠。"],
],
trends: [
"AI 整櫃重量增加，滑軌與機櫃改用更高強度的設計並加強承重測試",
"液冷普及後，機殼與機櫃要預留分歧管、快接頭與漏液偵測的空間",
"OCP 等開放規格機櫃普及，機構件設計從客製走向依標準規格量產",
"機殼廠由單純鈑金延伸到整機櫃組裝與系統整合服務",
],
