how: [
["在做什麼", "伺服器裡的晶片、主機板、電源和其他伺服器之間，要靠連接器與線材接起來。AI 機櫃裡的 GPU 需要彼此高速溝通，線材和連接器的數量與規格都大幅提升。"],
["怎麼運作", "GPU 插在插座上連到主機板，主機板再經板邊高速連接器接上銅纜，銅纜沿著機櫃背面把每個運算托盤接到交換托盤。高速銅纜用一對銅芯傳差分訊號，外面包絕緣與屏蔽減少干擾。"],
["關鍵名詞", "插座（Socket）：讓 CPU／GPU 與主機板接觸的底座。背板銅纜：機櫃後方集中連線的線束。AEC（主動式電纜）：線頭加上晶片補償訊號，讓銅線能傳得更遠。"],
["景氣看什麼", "AI 機櫃出貨量與架構（GPU 之間用銅線連得越多，線材用量越大）、傳輸速度升級（速度越快，設計越難、單價越高），以及短距離銅線和光纖之間的取捨。"],
["台灣角色", "貿聯-KY 做高速線材組件，嘉澤做 CPU／GPU 插座與連接器，正崴、信邦也供應連接器與線材，客戶包含伺服器代工廠與國際晶片廠。"],
],
trends: [
"機櫃內 GPU 互連以銅纜為主，速度每升級一代，線材與連接器規格都要重新設計",
"跨機櫃的短距離連線出現主動式電纜（AEC），介於被動銅線與光纖之間",
"插座接點數隨晶片封裝變大而增加，對平整度與散熱壓力的要求更高",
"更長距離或更高速度的連線，逐步由銅轉成光（共同封裝光學 CPO）",
],
