how: [
["在做什麼", "AI 叢集裡成千上萬顆 GPU 要互相傳資料，距離一遠，銅線的電訊號會衰減。光通訊把電訊號轉成光，在光纖裡跑得又快又遠，再在另一端轉回電。"],
["怎麼運作", "光收發模組插在交換器或網卡上：DSP 先整理電訊號，驅動晶片推動雷射快速閃爍，光經透鏡耦合進光纖；另一端的光偵測器把光變回電流，放大後再交給 DSP 還原資料。模組通常成對使用。"],
["關鍵名詞", "800G、1.6T：每秒能傳的資料量。雷射晶片：發光核心，用磊晶晶圓做成（EML、VCSEL 等）。DSP：補償訊號失真的晶片。CPO（共同封裝光學）：把光引擎直接封裝在交換晶片旁，縮短電訊號路徑。"],
["景氣看什麼", "雲端業者 AI 叢集建置規模、交換器規格升級（800G 往 1.6T）、雷射晶片供應是否吃緊，以及 CPO 等新架構導入時程對傳統模組的影響。"],
["台灣角色", "聯亞（雷射磊晶）、華星光（光元件）、上詮（光纖連接與 CPO）、光聖（光纖被動元件）、聯鈞、前鼎（模組）等，從磊晶、光學元件到模組組裝都有參與。"],
],
trends: [
"傳輸速度每一到兩年升級一代，模組由 800G 往 1.6T 以上發展",
"為了省電，出現拿掉或簡化 DSP 的線性驅動光模組（LPO／LRO）",
"共同封裝光學（CPO）把光引擎移到交換晶片旁，先導入交換器再擴及 GPU",
"雷射晶片與矽光子晶片成為產能瓶頸，供應鏈積極擴產與多元採購",
],
