how: [
["在做什麼", "資料中心裡每台伺服器都要連上網路才能互相傳資料，交換器就像路口的交通號誌，把每個資料封包送到正確的目的地。家裡和公司的 Wi-Fi、寬頻設備也屬於網通產品。"],
["怎麼運作", "每個機櫃頂端有一台交換器（ToR）連接櫃內伺服器，這些交換器再全部連到上層的骨幹交換器，任兩台伺服器之間只要經過少數幾跳就能互通；交換器裡的核心是交換晶片，連接埠插上光模組或銅纜。"],
["關鍵名詞", "交換晶片：決定交換器速度與連接埠數量的核心。ToR（Top of Rack）：機櫃頂端的交換器。葉脊架構：每台葉交換器都接到每台骨幹交換器。白牌交換器：代工廠設計生產、雲端業者自己裝軟體的交換器。"],
["景氣看什麼", "雲端業者資本支出與 AI 叢集規模、交換器速度升級（400G、800G 往更高）、交換晶片供應；寬頻與無線設備則看電信商標案、Wi-Fi 規格換代與庫存狀況。"],
["台灣角色", "智邦是資料中心白牌交換器的重要供應商，直接服務雲端業者；啟碁、智易、中磊等則做無線、寬頻與衛星通訊設備，客戶多為國際電信商與品牌。"],
],
trends: [
"AI 叢集把網路分成 GPU 之間的後端網路與一般前端網路，後端網路交換器需求快速增加",
"乙太網路在 AI 後端網路的採用提高，與專用互連技術並行發展",
"交換晶片頻寬每代翻倍，交換器改用液冷並開始導入共同封裝光學",
"家用網通朝 Wi-Fi 7 與光纖寬頻升級，衛星通訊設備成為新應用",
],
