how: [
["在做什麼", "把發電廠的電安全、穩定地送到每個用電的地方。這一路需要變壓器、開關設備、配電盤、電線電纜等「重電設備」，台灣稱為重電產業。"],
["怎麼運作", "發電廠先用變壓器把電壓升高，讓長距離輸電的損耗變小；到了城市附近的變電所再一步步降壓，最後由配電盤分配到各個迴路，交給工廠、資料中心與住家使用。"],
["關鍵零件", "變壓器：矽鋼片疊成的鐵心外繞銅線圈，泡在絕緣油裡散熱。GIS 氣體絕緣開關：體積小的高壓開關設備。配電盤：銅排加斷路器，短路時切斷保護。設備多為客製、交期長。"],
["景氣看什麼", "台電強韌電網等電網投資計畫、資料中心與半導體廠新建、再生能源併網量，以及美國等海外電網汰換需求帶來的外銷訂單、交期與報價。"],
["台灣角色", "華城、士電、中興電、亞力等廠商生產變壓器、GIS 與配電設備，供應台電與民間廠房，近年也把變壓器外銷到美國等海外市場；華新、大亞等則生產電線電纜。"],
],
trends: [
"資料中心與 AI 機房用電暴增，高壓變壓器與開關設備供不應求，交期拉長",
"美國等海外電網老舊需汰換，台灣重電廠的變壓器外銷比重提高",
"再生能源大量併網，電網需要更多變電所、儲能與智慧電網監控設備",
"電網強韌化：輸配電線路地下化、變電所分散布建，降低大停電風險",
],
