how: [
["在做什麼", "現代晶片有數百億個電晶體，不可能手畫。EDA 就是設計晶片用的專業軟體，IP 則是別人設計好、可以直接買來用的電路模組，例如 CPU 核心或高速介面。"],
["怎麼運作", "工程師用硬體描述語言寫出電路功能（RTL），軟體把它合成成邏輯閘，再自動擺放位置、拉好連線，經過大量模擬與硬體加速驗證確定沒有錯誤後，輸出光罩檔案交給晶圓廠製造。"],
["關鍵名詞", "EDA：電子設計自動化軟體。IP：可重複授權的電路模組。Tape-out：設計完成、交出光罩檔案的那一刻。硬體模擬器：用專用機器快速跑整顆晶片的驗證。"],
["景氣看什麼", "晶片設計案數量、先進製程導入、雲端與科技大廠自研晶片的趨勢；授權多為多年合約，營收比硬體穩定，也要留意出口管制的影響。"],
["代表公司", "Synopsys 與 Cadence 是 EDA 兩大廠，也賣 IP；Arm 授權處理器架構與 CPU 核心，Rambus 做記憶體介面 IP。台灣 IC 設計與設計服務公司、台積電製程都和這些工具緊密合作。"],
],
trends: [
"先進製程與小晶片（Chiplet）讓設計更複雜，EDA 擴展到多晶片封裝、熱與訊號的整合模擬",
"AI 輔助設計：用機器學習自動找最佳佈局、加速驗證，縮短設計時程",
"雲端與科技大廠自研 AI 晶片，設計案數增加，帶動 EDA 授權與設計服務需求",
"EDA 廠併購模擬軟體公司，從晶片延伸到系統層級的多物理模擬",
],
