how: [
["在做什麼", "設計 AI 運算用的晶片。GPU 能同時做大量平行計算，最適合訓練與執行 AI 模型；另外也有替雲端業者量身打造的客製 AI 晶片（ASIC）。"],
["怎麼運作", "晶片設計公司把設計交給晶圓廠生產，搭配 HBM 做先進封裝，再由伺服器廠組成 8 顆 GPU 的伺服器或整櫃系統，用高速互連與交換晶片把上萬顆 GPU 串成 AI 叢集。"],
["關鍵名詞", "CUDA：輝達的 GPU 程式開發平台，生態系是護城河。運算核心（SM）：GPU 裡大量重複的計算單元。ASIC：為特定用途設計的晶片。NVLink：GPU 之間的高速互連。"],
["景氣看什麼", "雲端業者資本支出、新一代平台的推出與量產時程、CoWoS 與 HBM 供應、出口管制，以及客製晶片與 GPU 之間的訂單消長。"],
["和台灣的關係", "這些晶片幾乎都由台積電生產與封裝，伺服器多由鴻海、廣達、緯創等台廠組裝，散熱、電源、PCB 也大量來自台灣供應鏈。"],
],
trends: [
"產品從單顆 GPU 走向整櫃系統，晶片商同時賣 CPU、GPU、交換器與軟體",
"雲端業者擴大自研 ASIC，與 GPU 並用以降低成本，帶動客製晶片設計服務",
"AI 需求從訓練轉向推論，重視每瓦效能與記憶體容量，HBM 搭載量持續提高",
"GPU 之間的互連走向更高速的銅線與共同封裝光學，叢集規模越做越大",
],
