how: [
["在做什麼", "把 GPU、CPU、記憶體、電源與散熱組裝成伺服器，再串成整櫃與整個機房；網路設備商則提供把成千上萬台機器連在一起的交換器。"],
["怎麼運作", "伺服器品牌向晶片商買零件，由代工廠組裝測試，常以「整櫃」形式出貨；機房裡每個機櫃透過葉層與骨幹交換器、光纖互連，讓多台 GPU 像一台大電腦一樣一起訓練模型。大型雲端也常直接向代工廠下單。"],
["關鍵名詞", "整櫃（rack-scale）：整個機櫃一起設計、一起交貨。NIC 網卡：伺服器連上網路的介面。葉層／骨幹：資料中心兩層式的交換器架構。乙太網路：資料中心最常見的網路標準。"],
["景氣看什麼", "雲端與企業的 AI 投資、GPU 新平台交貨時程、伺服器毛利率、網路升級到更高速度的進度，以及光模組供應是否吃緊。"],
["和台灣的關係", "美國品牌的伺服器大多由台灣代工廠（鴻海、廣達、緯創、英業達等）組裝，機殼、電源、散熱、PCB 與白牌交換器（如智邦）也多由台廠製造。"],
],
trends: [
"出貨單位從單台伺服器變成整櫃，組裝、測試與液冷整合的門檻提高",
"AI 叢集網路從專用互連轉向乙太網路，交換器速度持續升級",
"大型雲端直接向代工廠採購白牌伺服器與交換器，品牌廠轉攻企業與主權 AI 客戶",
"共同封裝光學（CPO）把光引擎放進交換器晶片旁，降低高速傳輸的耗電",
],
