how: [
["在做什麼", "把電網的電穩定、不中斷地送進資料中心的每一個機櫃。AI 機櫃耗電大增，供電設備從電網端到機櫃端都要擴充升級。"],
["怎麼運作", "高壓電進來後由變壓器降壓，開關設備負責切換與保護，再進 UPS：先整流成直流、替電池充電，再逆變回乾淨的交流，經配電單元送到機櫃。停電時 UPS 的電池先撐住，發電機啟動後接手供電。"],
["關鍵零件", "變壓器、開關設備、UPS（整流器、電池、逆變器）、配電單元（PDU）、母線槽與備援發電機；大型變壓器與燃氣渦輪機交期長，是蓋資料中心常見的瓶頸。"],
["景氣看什麼", "雲端業者資本支出、資料中心新建與電網併網進度、設備訂單與交期，以及電力公司的電網投資計畫。"],
["代表公司", "GE Vernova 做發電與電網設備，伊頓做配電與電源管理，Vertiv 做 UPS 與散熱，開拓重工、康明斯做備援發電機。台灣的電源、重電廠也供應部分設備。"],
],
trends: [
"AI 機櫃功率快速提高，資料中心配電改用更高電壓的直流架構，減少轉換損耗",
"電網併網排隊變長，資料中心自建燃氣發電、燃料電池等現場發電來源",
"變壓器、開關設備與燃氣渦輪機產能吃緊，設備商擴產並延長交期",
"電池儲能與 UPS 結合，除了備援也參與電網調度，平衡 AI 訓練造成的用電波動",
],
