how: [
["在做什麼", "找地、拉電、蓋建築、裝機電，把資料中心蓋起來，然後自己用或出租給雲端業者。AI 讓資料中心需求大增，電力工程、機電統包與資料中心租賃都跟著忙起來。"],
["怎麼運作", "開發商先取得靠近電網與光纖的土地並申請電力容量，蓋變電站接入電網；再發包土建與機電統包：建築主體、開關設備與 UPS、屋頂冷卻與管線。完工後分期上架機櫃，簽長約出租給雲端業者。"],
["關鍵名詞", "MW：資料中心常用「多少百萬瓦」描述規模。機電統包（MEP）：一次承包電力、空調、管線工程。併網：向電力公司申請接上電網。REIT：持有資料中心收租的不動產投資信託。"],
["景氣看什麼", "雲端業者的資本支出與租約、電網併網排隊時間、工程公司在手訂單、變壓器等長交期設備的供應，以及利率（影響 REIT 與開發商的資金成本）。"],
["代表公司", "Quanta Services、MYR Group 做電力工程，Comfort Systems、EMCOR 做機電工程，Sterling 做場地開發，Equinix 與 Digital Realty 經營資料中心租賃。台灣廠務工程公司也承接本地資料中心工程。"],
],
trends: [
"電力成為資料中心選址的第一條件，園區往電網容量充足或能自建發電的地方移動",
"單一園區規模越蓋越大，從數十 MW 走向數百 MW，工程改成分期交付",
"機電模組（電力撬裝、冷卻模組）在工廠預製後運到現場，縮短工期",
"AI 機櫃改用液冷，建築在設計階段就要預留冷卻水管路與更重的樓板承重",
],
