how: [
["在做什麼", "大型雲端業者在全球蓋資料中心，把運算、儲存與 AI 模型當成服務出租給企業與個人，是 AI 晶片與伺服器最大的買家。"],
["怎麼運作", "用戶按用量付費，雲端業者把營收投入資本支出，採購 GPU 或自研晶片、伺服器、網路設備並興建機房；每個區域分成幾個互相備援的可用區，算力擴充後再推出更多服務，收入成長又支撐下一輪投資，形成飛輪。"],
["關鍵名詞", "資本支出（CapEx）：買設備、蓋廠房的長期投資。可用區（AZ）：同一區域內電力與網路獨立的機房群。IaaS／PaaS／SaaS：出租算力、平台、軟體三種層次。自研晶片：例如 Google 的 TPU。"],
["景氣看什麼", "每季財報公布的資本支出與下一年指引、雲端營收成長率、AI 服務的收入貢獻、折舊壓力；它們加碼或縮手，會直接影響整條 AI 供應鏈。"],
["代表公司", "微軟 Azure、亞馬遜 AWS、Google Cloud、甲骨文 OCI，以及自建大型 AI 叢集的 Meta。它們的伺服器、晶片與零組件大量向台灣供應鏈採購。"],
],
trends: [
"雲端業者同時採購 GPU 與自研 ASIC，用自家晶片壓低推論成本、降低對單一供應商依賴",
"AI 叢集規模越蓋越大，電力取得速度成為擴建瓶頸，開始直接投資發電與購電合約",
"資本支出由一般伺服器轉向 AI 伺服器與網路，折舊費用上升，市場更在意 AI 服務能否回本",
"雲端服務往上層移動，把模型、代理程式與開發工具包成服務，提高每單位算力的收入",
],
