how: [
["在做什麼", "專門出租 GPU 算力的新興雲端公司（Neocloud）。AI 公司不想自己蓋機房，就向它們按時間租用大量 GPU 來訓練或執行模型；大型雲端算力不夠時也會向它們租。"],
["怎麼運作", "公司透過借款或發行股票籌錢，大量採購 GPU 伺服器，租用或自建有足夠電力的機房，用高速網路把上萬顆 GPU 串成叢集，再與客戶簽多年合約，按 GPU 使用時數收租金。合約常被拿來當借款擔保。"],
["關鍵名詞", "Neocloud：專做 GPU 租賃的新型雲端。GPU 小時：租用一顆 GPU 一小時的計價單位。折舊：GPU 價值隨時間與新世代推出而下降。在手訂單：已簽約、尚未認列的未來收入。"],
["景氣看什麼", "新簽合約與在手訂單、GPU 租金走勢、借款利率與負債比、機房電力取得速度、客戶是否過度集中；要看累積租金能不能在 GPU 過時前超過購置成本。"],
["代表公司", "CoreWeave、Nebius、IREN 等；不少比特幣礦場因為手上有電力與土地，轉型成 AI 機房出租。它們採購的 GPU 伺服器多由台灣代工廠組裝，是台灣 AI 伺服器供應鏈的客戶之一。"],
],
