how: [
["在做什麼", "MLCC（積層陶瓷電容）是電路板上數量最多的小零件，像小水庫一樣存放與釋放電，讓晶片拿到穩定、乾淨的電壓。電解電容則用在需要大容量的電源電路。"],
["怎麼運作", "把鈦酸鋇陶瓷粉調成漿料、塗成極薄的薄膜，印上鎳內電極，疊上數百層後壓合、切成小粒，在上千度高溫燒結，再加上兩端的端電極。內電極左右交錯接到兩端，層數越多、每層越薄，電容量越大。"],
["關鍵名詞", "MLCC：積層陶瓷電容。介電層：電極之間的陶瓷層。車規：耐高溫、高可靠度的車用等級。鋁電解電容：把鋁箔與電解液捲起來，容量大，常用在電源供應器。"],
["景氣看什麼", "手機與電腦出貨、AI 伺服器與電動車的單機用量提升、通路庫存與報價；高容量、小尺寸與車規產品技術門檻高、利潤較好。"],
["代表公司", "村田、太陽誘電、TDK 在高階 MLCC 領先，日本貴彌功與 Nichicon 是鋁電解電容大廠，住友金屬礦山供應鎳粉。台灣的國巨、華新科也生產 MLCC，與日廠在不同等級產品競爭。"],
],
trends: [
"AI 伺服器 GPU 功耗大，板上需要更多高容量 MLCC 穩壓，單機用量明顯增加",
"介電層越做越薄、層數越疊越多，在更小尺寸裡塞進更大容量",
"電動車與自駕系統需要耐高溫、耐高壓的車規電容，產品組合往高階移動",
"材料粉體與內電極微細化是競爭關鍵，日廠多自製關鍵材料",
],
chain: [
{ tier: "上游", title: "材料", items: [
{ name: "陶瓷粉（鈦酸鋇）", desc: "介電層的主要材料，粒徑越細越能做薄", c: [["4078.T", "堺化學", "鈦酸鋇粉"], ["6981.T", "村田製作所", "自製陶瓷材料"]] },
{ name: "內電極材料（鎳粉）", desc: "印在每層陶瓷薄膜上的金屬電極", c: [["5713.T", "住友金屬礦山", "鎳粉"]] },
] },
{ tier: "中游", title: "被動元件製造", items: [
{ name: "MLCC", desc: "塗佈、印刷、疊層、燒結，做成積層陶瓷電容", c: [["6981.T", "村田製作所", "MLCC 龍頭"], ["6976.T", "太陽誘電", "MLCC"], ["6762.T", "TDK", "MLCC"], ["2327", "國巨", "台灣 MLCC"], ["2492", "華新科", "台灣 MLCC"]] },
{ name: "鋁電解電容", desc: "鋁箔與電解液捲繞而成，用在大容量電源電路", c: [["6997.T", "日本貴彌功", "鋁電解電容"], ["6996.T", "Nichicon", "鋁電解電容"]] },
{ name: "電感與其他被動元件", desc: "電源電路裡搭配電容濾波、儲能的電感", c: [["6762.T", "TDK", "電感"], ["6981.T", "村田製作所", "電感"]] },
] },
{ tier: "下游", title: "應用", items: [
{ name: "AI 伺服器、車用、手機", desc: "主機板與電源上大量使用，用量隨功耗提高", c: [["2382", "廣達", "AI 伺服器"], ["6902.T", "電裝", "車用電子"]] },
] },
],
