how: [
["在做什麼", "晶片製造需要上百種設備與材料。日本廠在矽晶圓、光阻、塗佈顯影、測試機、切割研磨與光罩檢測等環節都有很強的地位，是全球晶圓廠與封測廠的重要供應商。"],
["怎麼運作", "矽晶圓進廠後，反覆經過塗光阻、曝光、顯影、蝕刻、成膜、洗淨等步驟，一層層堆出電路；完成後先做晶圓測試，再背面研磨磨薄、切成一顆顆晶粒，封裝後做成品測試才出貨。"],
["關鍵名詞", "塗佈顯影：在晶圓上塗光阻並把曝光後的圖案顯現出來。光罩檢測：確認電路「底片」沒有瑕疵。成膜：在晶圓上長出薄膜。測試機：檢查每顆晶片功能與速度是否合格。"],
["景氣看什麼", "全球晶圓廠資本支出、先進製程與 HBM 擴產、AI 晶片越複雜測試時間越長、出口管制與中國需求的變化，以及日圓匯率。"],
["代表公司", "東京威力科創、國際電氣、SCREEN、Lasertec、迪思科、東京精密、愛德萬測試，以及矽晶圓的信越化學與 SUMCO、光阻的東京應化。台積電等台灣晶圓廠與封測廠是它們的重要客戶。"],
],
trends: [
"AI 晶片與 HBM 的測試項目變多、時間變長，高階測試機需求跟著提高",
"先進封裝與 HBM 需要把晶圓磨得更薄、切得更精準，研磨切割設備重要性上升",
"製程走向 GAA 與背面供電，成膜、蝕刻與洗淨步驟增加，設備用量跟著增加",
"出口管制與供應鏈在地化，讓設備廠的客戶與地區組合持續調整",
],
