how: [
["在做什麼", "晶圓代工是「替別的公司製造晶片」的生意。韓國有三星的先進製程代工，也有 DB HiTek 這類專做 8 吋特殊製程的代工廠。"],
["怎麼運作", "IC 設計公司用 EDA 工具與矽智財完成設計後下單，代工廠用曝光、蝕刻、成膜等設備在晶圓上做出電路，再交給封測廠切割封裝。先進製程做手機處理器與 AI 晶片；特殊製程做電源管理、驅動 IC、感測器等。"],
["關鍵名詞", "GAA：閘極包住通道四面的電晶體結構，三星較早導入。FinFET：閘極包住三面的鰭式電晶體。8 吋特殊製程：不追求最小線寬，重視耐高壓、類比等特性。良率：一片晶圓中合格晶片的比例。"],
["景氣看什麼", "先進製程的良率與大客戶訂單、產能利用率、消費電子與車用景氣；特殊製程的價格與產能利用率也常受中國同業擴產影響。"],
["和台灣的關係", "三星在先進製程與台積電直接競爭，DB HiTek 與台灣的世界先進、力積電等在特殊製程市場重疊；客戶常比較兩地的良率、價格與交期。"],
],
trends: [
"先進製程全面轉向 GAA 電晶體，良率爬升速度決定能否拿到大客戶訂單",
"代工廠爭取 AI 與車用晶片客戶，並把先進封裝一起打包成整套服務",
"8 吋特殊製程往功率半導體與第三代半導體延伸，用特性而非線寬競爭",
"供應鏈在地化讓客戶傾向多找一家代工來源，分散單一地區風險",
],
