how: [
["在做什麼", "先進封裝把多顆晶片精準疊放、並排後連成一顆，製程很像縮小版的晶圓廠。每一道步驟都需要專門的機台，這些設備商就是封裝擴產時最先接單的一群。"],
["怎麼運作", "晶圓先經濕製程清洗、蝕刻、去光阻；切好的晶片由挑揀黏晶機精準放到中介層或載板；點膠機把底部填充膠灌進縫隙；壓膜機與烤箱加熱固化；最後由自動光學檢測找出缺陷。"],
["關鍵名詞", "濕製程：用化學藥液清洗或蝕刻。黏晶：把晶片放到指定位置並固定。Underfill：填在晶片下方的保護膠。AOI：自動光學檢測。"],
["景氣看什麼", "晶圓廠與封測廠的先進封裝擴產計畫、設備交機與驗收時程、製程從 CoWoS 走向 SoIC、面板級封裝時是否需要新機台。"],
["台灣角色", "過去封裝設備多由國外大廠供應，近年台灣設備商在濕製程、點膠、黏晶、烘烤與檢測打進先進封裝產線，受惠於在地化採購與快速服務。"],
],
trends: [
"晶片堆疊從微凸塊走向混合鍵合，對清洗潔淨度與對位精度的要求更高",
"晶圓級封裝往方形面板級封裝發展，機台要重新設計以處理大尺寸面板",
"封裝越大越容易翹曲，壓膜、烘烤與量測設備需要更精準的溫度與壓力控制",
"晶圓廠與封測廠擴產帶動設備在地化採購，台灣設備商的交期與服務成為優勢",
],
