how: [
["在做什麼", "AI 晶片越做越大，傳統有機材料的載板在高溫下容易翹曲、線路也難再變細。玻璃基板是把載板中間的核心層換成玻璃，讓大尺寸封裝更平整、更穩定。"],
["怎麼運作", "先在大片玻璃上用雷射改質再蝕刻出細小穿孔（TGV），孔內鍍上金屬導電，兩面再一層層做增層線路，最後把晶片放上去封裝，玻璃負責支撐與上下導通。"],
["關鍵名詞", "TGV：玻璃穿孔，讓上下層線路連通。玻璃核心：取代有機核心板的那一層。面板級封裝：用方形大面板取代圓形晶圓來封裝，玻璃是常見載具。"],
["景氣看什麼", "晶片大廠與載板廠的導入時程、雷射鑽孔與金屬化的良率、玻璃易碎的搬運問題能否解決；目前多在研發與小量試產，量產時點仍有不確定性。"],
["台灣角色", "載板廠與面板廠投入玻璃核心與面板級封裝研發，台灣設備商供應雷射鑽孔、壓膜烘烤、濕製程等機台，玻璃加工廠也嘗試切入。"],
],
trends: [
"大尺寸 AI 封裝的翹曲問題，推動載板核心從有機材料研究改用玻璃",
"封裝從圓形晶圓走向方形面板，玻璃同時被用作面板級封裝的載具",
"雷射改質加蝕刻成為 TGV 主流做法，鑽孔速度與金屬化良率是量產關鍵",
"面板廠利用既有大尺寸玻璃產線轉作封裝，跨入半導體後段製程",
],
