how: [
["在做什麼", "電源送來 12V 或更高電壓，但 GPU 只要不到 1V、卻要上千安培的電流。降壓電路靠開關快速切換，再由電感和電容把脈衝電流「抹平」成穩定的低電壓。"],
["怎麼運作", "電流通過線圈時會在磁性材料裡建立磁場，把能量暫存起來；開關斷開時磁場釋放能量繼續供電。把磁粉和線圈壓成一體成型，體積小、漏磁少、可承受大電流。"],
["關鍵零件", "磁性材料（金屬粉、鐵氧體）決定能存多少能量與損耗；銅線圈決定電阻與發熱；飽和電流：超過就失去作用，AI 伺服器要求越來越高。"],
["景氣看什麼", "AI 伺服器 GPU 功耗與電源相數增加、車用電子化、手機與筆電庫存循環；高電流電感規格門檻高，供應商需要通過客戶長時間驗證。"],
["台灣角色", "台灣有多家電感與磁性元件廠，產品從一般電感到伺服器用大電流一體成型電感都有，部分電源大廠也自製磁性元件，上游有鐵氧體磁粉廠。"],
],
trends: [
"GPU 電流越來越大，VRM 相數增加，每片主機板使用的大電流電感變多",
"供電模組往 GPU 正下方移動（垂直供電），電感要更薄、更耐熱",
"金屬粉末一體成型電感取代傳統鐵氧體繞線電感，承受更高飽和電流",
"電源架構往高壓直流發展，帶動高頻、低損耗磁性元件的設計需求",
],
