how: [
["在做什麼", "數位電路要靠統一的節拍才能同步運作，傳資料也要對準頻率。石英晶體能產生極穩定的振動頻率，做成晶體或振盪器，就是電子產品裡的「心跳」。"],
["怎麼運作", "人工培養的水晶切成薄片，薄片厚度決定振動頻率；兩面鍍上電極後通電，石英因壓電效應開始規律振動，再封裝成小元件，搭配電路輸出時脈訊號。"],
["關鍵名詞", "壓電效應：受電會變形、受力會產生電。Crystal：被動的石英晶體。Oscillator：內含電路、直接輸出時脈的振盪器。溫補（TCXO）：溫度變化下也維持精準。"],
["景氣看什麼", "手機與電腦出貨、網通與伺服器升級（高速傳輸要高頻低雜訊）、車用電子與低軌衛星需求；高頻、高精度與小尺寸產品的比重越高，產品組合越好。"],
["台灣角色", "台灣是全球石英元件主要產地之一，與日本廠商同為主要供應者，台廠產品涵蓋晶體、振盪器到高頻高精度元件，並延伸到 AI 伺服器與車用市場。"],
],
trends: [
"AI 伺服器與高速網通傳輸速度提升，帶動高頻、低抖動振盪器需求",
"元件尺寸持續縮小，晶片更薄、封裝更小，加工精度要求提高",
"車用電子與低軌衛星需要耐溫、耐震的高可靠度頻率元件",
"MEMS 矽振盪器在部分應用與石英競爭，石英廠以高精度與穩定性區隔",
],
