how: [
["在做什麼", "手機裡空間很擠，螢幕、鏡頭、電池和主機板不在同一個平面上，需要能彎折、很薄的電路把它們連起來。軟板就是做在 PI 塑膠薄膜上的電路板。"],
["怎麼運作", "PI 薄膜和銅箔貼合成軟性銅箔基板，經曝光、顯影、蝕刻做出線路，鑽孔電鍍做出上下層導通孔，再貼上覆蓋膜保護，需要硬度的地方加補強板，最後打件、成型後交給組裝廠。"],
["關鍵名詞", "FPC：軟性印刷電路板。FCCL：軟性銅箔基板，是軟板的原料。PI：聚醯亞胺，耐高溫的薄膜。覆蓋膜：保護線路的絕緣膜。軟硬結合板：一塊板子同時有硬的與可彎折的區域。"],
["景氣看什麼", "手機（特別是高階機種）的出貨與新機規格、摺疊機與穿戴裝置、電動車電池模組的採用；軟板客戶集中，單一品牌的訂單變化影響很大。"],
["台灣角色", "台灣軟板廠是國際大品牌的重要供應商，上游也有軟性銅箔基板與 PI 薄膜材料廠，供應鏈從材料、基板到軟板成品相對完整。"],
],
trends: [
"高速傳輸需求讓軟板材料從 PI 延伸到低損耗的 LCP 與改質 PI",
"摺疊手機與穿戴裝置增加需要反覆彎折的軟板，耐折性成為規格重點",
"電動車電池模組用軟板取代傳統線束採集電壓與溫度，打開車用市場",
"線路越做越細，軟板也導入類似載板的細線路製程與高密度打件",
],
