how: [
["在做什麼", "一台手機或伺服器裡，不同晶片需要的電壓都不一樣，而且要非常穩定。電源管理 IC 負責把輸入電源轉成多組精準電壓、依序開關，並在過壓、過熱時保護系統。"],
["怎麼運作", "PMIC 控制功率開關（MOSFET）每秒切換幾十萬次以上，搭配電感與電容把電壓降下來並濾平；回授線路隨時量測輸出電壓並修正。LDO 用在要求低雜訊的電路，AC/DC 控制 IC 則用在充電器把市電轉成直流電。"],
["關鍵名詞", "PMIC：整合多組電源的管理晶片。Buck：降壓轉換器。LDO：低壓差穩壓器，雜訊小。BCD 製程：能同時做類比、數位與高壓元件的成熟製程。類比 IC：處理連續訊號的晶片。"],
["景氣看什麼", "消費電子與筆電庫存循環、AI 伺服器與車用電源規格提升、中國廠商的價格競爭；類比 IC 產品多、生命週期長，景氣波動通常比數位晶片平緩。"],
["台灣角色", "台灣有多家電源管理 IC 設計公司，產品用在筆電、主機板、顯示卡、手機與伺服器，並朝車用與高效率電源發展；晶片多交給台灣晶圓廠的 BCD 成熟製程生產。"],
],
trends: [
"AI 伺服器處理器電流大增，電源架構往多相降壓與更靠近晶片的供電方式演進",
"伺服器機櫃改用較高的直流電壓配電，帶動新的電源轉換與控制 IC 需求",
"車用電子化讓電源 IC 需要通過車規認證，產品驗證時間長但生命週期也長",
"快充與高效率電源導入氮化鎵功率元件，控制 IC 與功率元件整合程度提高",
],
