how: [
["在做什麼", "手機拍照、車子辨識路況、螢幕自動調亮度、機器人避障，都要先把光轉成電訊號。光感測元件就是電子產品的「眼睛」，從影像到明暗、距離都能量。"],
["怎麼運作", "光經過鏡頭打到感測器，每個像素上方的微透鏡把光集中，彩色濾光片只讓特定顏色通過，下方光二極體把光子轉成電子，經金屬線路讀出成數位訊號，再交給影像處理晶片（ISP）運算。"],
["關鍵名詞", "CIS：CMOS 影像感測器。微透鏡與彩色濾光片：決定進光量與顏色。晶圓級封裝：整片晶圓一起封裝再切割，體積小。ToF：用光飛行時間量距離。光耦合器：用光傳訊號、讓兩邊電路絕緣。"],
["景氣看什麼", "手機鏡頭數與規格升級、車用 ADAS 鏡頭數量、監控與工業視覺、機器人的導入；影像感測器主要由國際大廠設計，台廠多在代工、製程、封裝與特定感測 IC。"],
["台灣角色", "台灣提供影像感測器的晶圓代工、彩色濾光與微透鏡製程、晶圓級封裝，也有光學感測 IC 設計公司、鏡頭廠與光耦合器、紅外線元件廠。"],
],
trends: [
"影像感測器走向堆疊式結構，把像素層和邏輯運算層分開製造再接合",
"車用 ADAS 與自駕需要更多鏡頭，車規 CIS 與高動態範圍規格需求提升",
"感測器內建 AI 運算，在感測端先做辨識，減少傳到處理器的資料量",
"機器人與工業視覺帶動 3D 感測、ToF 與紅外線元件的新應用",
],
