how: [
["在做什麼", "XR 頭戴裝置要把影像送到離眼睛只有幾公分的地方，還要看起來清楚、不暈、不重。VR 把整個視野換成虛擬畫面；AR 讓虛擬影像疊在真實世界上，眼鏡要做得像一般眼鏡。"],
["怎麼運作", "VR 用高解析度的微型顯示器，光經 Pancake 鏡片的半反射面與反射式偏光片來回摺返，縮短機身長度；AR 用小型光機把影像打進光波導，光在鏡片裡全反射前進，到出光區再射向眼睛，同時讓外界的光透進來。"],
["關鍵名詞", "Micro OLED：做在矽晶圓上的小尺寸高解析顯示器。Pancake：摺返式光學鏡片。光波導：讓光在薄鏡片內傳遞的元件，用光柵把光導入與導出。6DoF 追蹤：用鏡頭與感測器偵測頭部與手部位置。"],
["景氣看什麼", "國際品牌新裝置的推出與銷量、AI 眼鏡的普及速度、光波導與微型顯示器的成本；市場仍在發展期，出貨量受少數品牌產品週期影響很大。"],
["台灣角色", "台廠供應光學鏡頭與鏡片、投影光機、微光學元件與組裝，也有晶圓廠與封測廠參與微型顯示器與感測器的製造。"],
],
