how: [
["在做什麼", "汽車由上萬個零件組成，其中轉向、煞車、傳動、引擎等系統需要大量高精度金屬零件。這個題材聚焦在這些機械精密件，和車用電子、連接器是不同的段落。"],
["怎麼運作", "鋼或鋁材先加熱後放進上下模具鍛造，或鑄造成大致形狀，再用 CNC 車床、銑床夾住工件切削到微米等級精度，經熱處理提高強度、表面處理防鏽，用量測儀全數檢測後交給一階供應商組成模組，再送到車廠。"],
["關鍵名詞", "Tier 1：直接供貨給車廠的一階供應商，例如煞車、轉向系統大廠。IATF 16949：車用品質管理認證。PPAP：新零件量產前的核准程序。輕量化：用鋁、新材料減重。"],
["景氣看什麼", "全球汽車銷量、歐美車廠與一階供應商的庫存、匯率與關稅、電動車轉型速度；引擎相關零件長期可能減少，電驅、煞車與轉向電子化帶來新零件需求。"],
["台灣角色", "台廠多為國際一階供應商的精密件協力廠，以多樣少量、彈性生產與成本控制見長，部分廠商在海外設廠就近服務客戶，也延伸到電動車與其他產業的精密零件。"],
],
trends: [
"電動車減少引擎與變速箱零件，電驅系統、減速齒輪與散熱件需求增加",
"線控煞車與線控轉向普及，機械零件和感測、馬達整合得更緊密",
"輕量化帶動鋁合金鍛造與一體化壓鑄，零件數減少但單件更大更複雜",
"關稅與供應鏈調整讓一階供應商分散採購，台廠在海外設廠就近供貨",
],
