how: [
["在做什麼", "電子產品裡的零件不會全部焊死，螢幕、電池、鍵盤、擴充卡、外接線都要能插拔與更換，連接器就是讓兩端接起來又能拆開的介面。這個題材聚焦在消費電子、電腦與工業用的一般連接器。"],
["怎麼運作", "銅合金薄片在連續模具裡一站站沖壓、折彎成端子，接觸點鍍金、其他部分鍍錫以降低接觸電阻、防氧化；塑膠粒射出成型做出外殼，再把端子插進外殼組成連接器，檢測後焊到電路板或接上線材。"],
["關鍵名詞", "端子：導電的金屬接點。料帶：連續沖壓時把端子串在一起的金屬帶。板對板：兩塊電路板互接。線對板：線材接到電路板。LGA 插槽：處理器用彈片接觸的插座。Type-C：常見的 USB 連接介面規格。"],
["景氣看什麼", "筆電、手機、家電與工業設備的出貨、新傳輸規格（如 USB4、Type-C 普及）、伺服器平台換代、銅價與匯率；產品單價低但種類多，模具開發速度與客戶分散度影響競爭力。"],
["台灣角色", "台灣連接器廠商眾多，長期供應筆電、手機、主機板與工業設備客戶，擅長快速開模與客製化，部分廠商也延伸到伺服器、車用與儲能產品。"],
],
trends: [
"AI 伺服器的處理器插槽與高速連接器腳數變多，規格與單價同步提升",
"傳輸速度提高讓連接器要兼顧訊號完整性，高速線材與連接器一起設計",
"Type-C 成為消費電子共通介面，各國法規推動充電介面統一",
"台廠從消費電子延伸到伺服器、車用與儲能，降低單一市場的景氣影響",
],
