/* 精細版（新題材）：儲能系統、太陽能與分散式儲能、電池關鍵材料、核能發電與 SMR、水資源工程與環保、EPC 廠務工程、CNC 工具機、工業自動化、醫療耗材與植入物、醫療器材、體外診斷 IVD、新藥研發與再生醫療 */
