how: [
["在做什麼", "太陽能中午最多、晚上沒有，風電也忽大忽小。儲能系統就像一個超大的行動電源，電多的時候先存起來，缺電的時候再放出去，讓電網保持穩定，也能當工廠與資料中心的備援電力。"],
["怎麼運作", "電網的交流電經過變壓器降壓，再由 PCS（電力轉換系統）用 IGBT 開關轉成直流電充進電池櫃；要用時反向轉回交流電送出。BMS 隨時監看每顆電芯的電壓與溫度，EMS 則像調度員，根據電價與電網指令決定何時充、何時放。"],
["關鍵名詞", "PCS：交流、直流雙向轉換。BMS：電池管理系統，防止過充過熱。EMS：能源管理系統。調頻：秒級反應穩定電網頻率。削峰填谷：離峰充電、尖峰放電。貨櫃內還有空調與消防系統，避免熱失控。"],
["景氣看什麼", "政府再生能源與儲能目標、電力公司調頻服務的招標與價格、電池芯價格（通常佔系統成本最大塊）、案場安全規範與併網進度，以及資料中心對備援電力的需求。"],
["台灣角色", "台廠參與電池模組、PCS 電力轉換、變壓器與開關設備、系統整合與案場建置；電芯多半向國外大廠採購，台灣強在電力電子與整合能力。"],
],
trends: [
"電芯走向更大容量的磷酸鋰鐵方形電芯，一個貨櫃能存的電越來越多",
"儲能從調頻轉向長時間的削峰填谷，案場由小時級往更長的放電時間發展",
"資料中心把儲能當成備援電力與用電調節工具，和 UPS 的界線變模糊",
"安全規範趨嚴，液冷電池櫃、分區消防與熱失控偵測成為標準配備",
],
