how: [
["在做什麼", "用半導體材料把陽光直接變成電。大型電廠蓋在地面或水面上，小型的裝在工廠、住家屋頂自己用，再配上小型儲能，就是「分散式」能源。"],
["怎麼運作", "陽光穿過玻璃照進矽晶電池片，PN 接面把被光打出來的電子推向正面的銀線，形成直流電；幾十片串起來、加玻璃、膠膜、背板與邊框封裝成模組。逆變器把直流電轉成交流電，經電表賣給電網，或自用並把多的電存進電池。"],
["關鍵名詞", "轉換效率：陽光有多少比例變成電。PERC、TOPCon、HJT：電池片的不同技術世代。逆變器：直流轉交流的設備。躉購：電力公司用固定價格收購綠電。自發自用：發的電優先給自己用。"],
["景氣看什麼", "多晶矽與模組價格（中國產能影響很大）、各國綠電政策與補助、企業 RE100 綠電採購需求、儲能電池價格，以及電網併網容量是否足夠。"],
["台灣角色", "台灣早年是電池片大國，後來被中國低價競爭壓縮；現在多轉向在地市場、高效率產品、逆變器、電廠開發營運與綠電售電。"],
],
trends: [
"電池片技術由 PERC 轉向 TOPCon 與 HJT，效率提升但製程與設備跟著改變",
"企業綠電採購需求增加，電廠開發商轉型為長期售電與綠電交易的服務商",
"屋頂型太陽能搭配小型儲能與混合式逆變器，自發自用比例提高",
"各國推動在地製造與供應鏈溯源，非中國產能與高效率模組有差異化空間",
],
