how: [
["在做什麼", "讓城市與工廠有乾淨的水可以用，並把用過的水和垃圾妥善處理。台灣降雨集中、科技廠用水量大，讓「水」與「廢棄物」成為重要的基礎建設產業。"],
["怎麼運作", "水庫的水先到淨水廠：加藥讓雜質結成大顆粒（混凝），在池子裡沉下去（沉澱），再經砂層過濾、加氯消毒，由泵浦加壓經管網送到用戶。污水經下水道進污水處理廠，在曝氣池用微生物分解污染物，沉澱後放流，或再經薄膜過濾變成再生水回供工廠。"],
["關鍵名詞", "BOT／ROT：民間出資興建營運、期滿交還政府。再生水：處理到可工業使用的回收水。薄膜過濾（MBR、RO）：用細孔濾掉雜質。焚化發電：燒垃圾的熱拿來發電，灰渣再送掩埋或再利用。"],
["景氣看什麼", "政府水利與下水道預算、科學園區用水與再生水計畫、乾旱缺水事件、廢棄物處理費率與焚化廠售電收入，以及長期特許營運合約的得標與續約情況。"],
["台灣角色", "國內業者多以「工程＋長期營運」模式賺取穩定收入，例如污水廠與焚化廠的特許經營，現金流相對穩定，較不受電子景氣影響。"],
],
trends: [
"科技廠用水量大，再生水廠與廠內回收系統成為新建園區的標準配備",
"污水處理從單純放流，轉向用薄膜把水回收再利用，處理等級越來越高",
"老舊焚化廠進入整建更新，提升發電效率並延長營運年限",
"減碳與循環經濟要求增加，灰渣、污泥等副產物的再利用越來越重要",
],
