how: [
["在做什麼", "晶圓廠裡一顆灰塵就可能毀掉晶片，所以廠房要做成超乾淨的無塵室，還要供應超純水、特殊氣體與化學品。EPC 廠務工程就是把這整套「工廠的生命系統」設計並蓋出來。"],
["怎麼運作", "天花板的風扇過濾單元（FFU）不斷往下吹乾淨空氣；機台站在有孔的高架地板上，氣流穿過地板回到次樓層。次樓層佈滿特殊氣體、超純水與化學品主管線，再分接到每台機台；廢氣送到屋頂洗滌塔，廢水回收處理。外圍還有變電站、冰水主機與超純水廠。"],
["關鍵名詞", "EPC：設計（Engineering）、採購（Procurement）、施工（Construction）。無塵室等級：每立方空間允許的微粒數。Hook-up：把機台接上各種管線的二次配工程。Sub-fab：放泵浦與管線的次樓層。"],
["景氣看什麼", "晶圓廠與先進封裝的資本支出、新廠動土與擴廠時程、在手訂單（未完工合約）金額、海外建廠帶來的新市場與成本風險，以及工程毛利率。"],
["台灣角色", "台灣廠商跟著晶圓廠累積大量無塵室與廠務經驗，也隨客戶到美國、日本、歐洲與東南亞建廠，是半導體供應鏈中「蓋廠」的關鍵角色。"],
],
trends: [
"台灣廠務工程商隨晶圓廠到海外建廠，承接美國、日本與歐洲的新廠工程",
"先進封裝廠與 AI 資料中心也需要無塵室與機電統包，客戶範圍擴大",
"製程越先進，超純水與特殊氣體的純度要求越高，廠務系統單價跟著提高",
"節能與水回收成為新廠設計重點，冰水、排氣與廢水系統往高效率發展",
],
