how: [
["在做什麼", "CNC（電腦數值控制）工具機用程式指揮刀具，在金屬塊上鑽孔、銑削、車削，做出精度到微米等級的零件。幾乎所有機械產品的零件都要經過它，所以被稱為「工業之母」。"],
["怎麼運作", "工程師把設計圖轉成 G 碼程式，控制器依指令驅動伺服馬達；馬達轉動滾珠螺桿，把旋轉變成直線移動，讓工作台沿著線性滑軌精準走位；主軸馬達帶著刀具高速旋轉切削工件，切削液負責降溫排屑，刀庫則自動換上下一把刀。"],
["關鍵零件", "控制器（多來自日本、德國）、主軸、滾珠螺桿、線性滑軌、伺服馬達、減速機與刀庫。多軸（五軸）機可一次從不同角度加工複雜曲面，單價與技術門檻更高。"],
["景氣看什麼", "全球製造業投資與 PMI、汽車與航太訂單、中國市場需求、日圓匯率（日本是主要對手）、關稅與出口管制，以及廠商接單到出貨的訂單能見度。"],
["台灣角色", "台灣是全球主要工具機出口國之一，中部有完整的整機與零組件聚落；上游的螺桿、滑軌、減速機也有具國際競爭力的廠商。"],
],
trends: [
"加工需求從三軸往五軸與複合加工發展，一台機器完成更多工序",
"工具機加上感測器與聯網功能，可監控主軸狀態並預測保養時間",
"航太、半導體設備與醫療零件等高精度應用，比傳統汽車零件更重視精度",
"供應鏈移往東南亞、印度與北美，帶動當地新設工廠的設備需求",
],
