how: [
["在做什麼", "讓工廠少靠人力、多靠機器自己完成重複又精準的工作，並用數據找出瓶頸與不良原因，做到「智慧製造」。缺工、工資上漲與供應鏈搬遷都推動這股需求。"],
["怎麼運作", "相機與光電感測器先「看見」產品位置與外觀；PLC 控制器依程式判斷下一步，命令驅動器帶動伺服馬達讓輸送帶走位、氣壓缸把不良品推出去、機械手臂夾取良品。產線資料再送到工業電腦、MES 與雲端分析，回頭調整參數。"],
["關鍵名詞", "PLC：可程式邏輯控制器，產線的小大腦。伺服馬達：可精準控制位置與速度。氣動元件：用壓縮空氣推動的汽缸與閥。MES：製造執行系統。數位分身：在電腦裡模擬一條產線。協作機器人：可與人一起工作的手臂。"],
["景氣看什麼", "全球製造業資本支出與 PMI、半導體與電子廠擴產、電動車與電池廠投資、中國市場需求，以及工業電腦與自動化元件的庫存循環。"],
["台灣角色", "台灣在工業電腦、氣動元件、傳動元件、驅動器與伺服系統都有國際級廠商，常以高 CP 值打進全球自動化供應鏈。"],
],
trends: [
"機器視覺加入 AI 模型，瑕疵檢測從固定規則改為自動學習判斷",
"協作機器人與自主移動機器人普及，小批量多樣的產線也能自動化",
"工廠數據集中到邊緣運算與雲端平台，用數位分身先模擬再調整產線",
"供應鏈分散到多國設廠，新廠一開始就以高自動化設計來因應缺工",
],
