how: [
["在做什麼", "醫療耗材是醫院天天在用、用完就丟的產品，如血袋、輸液管、針具、隱形眼鏡；植入物則是要放進人體、長期留在裡面的產品，如骨釘骨板、人工關節、牙科植體。"],
["怎麼運作", "醫療級塑膠或矽膠在無塵室射出成型、組裝成管路、血袋與針具；鈦合金等金屬則精密加工成植入物。產品密封包裝後用環氧乙烷（EO）或輻射滅菌，通過驗證並取得衛生主管機關許可，才能自有品牌銷售或代工給國際品牌，再送到醫院與通路。"],
["關鍵名詞", "滅菌：殺死所有微生物。生物相容性：材料放進人體不會引起不良反應。510(k)：美國 FDA 常見的醫材上市途徑。OEM／ODM：替國際品牌代工或設計製造。健保給付：影響國內售價與用量。"],
["景氣看什麼", "醫療需求相對穩定，主要看人口老化帶動的手術量與洗腎人數、新產品取證與海外通路拓展、國際品牌的代工訂單、健保價格調整，以及原料與匯率變化。"],
["台灣角色", "台灣擅長精密製造，在透析與血液耗材、注射耗材、隱形眼鏡代工與骨科植入物都有廠商，並以外銷與代工為重要成長來源。"],
],
trends: [
"人口老化帶動洗腎、骨科手術與慢性病照護需求，耗材用量穩定成長",
"隱形眼鏡往矽水膠材質、日拋與功能型鏡片發展，代工技術門檻提高",
"國際品牌為分散供應風險，把部分耗材代工訂單移往台灣等地",
"植入物導入 3D 列印與客製化設計，配合病人骨骼形狀製作",
],
