how: [
["在做什麼", "醫療器材幫醫師與病人「量得到、看得到、治得到」：量血壓血氧的監測設備、看身體內部的超音波等影像設備，以及呼吸治療、病床、輪椅等治療與照護設備。"],
["怎麼運作", "血氧夾讓紅光與紅外光穿過手指，光感測器量到的強弱變化反映血氧；壓脈帶充氣後由壓力感測器量血壓。類比前端晶片（AFE）把微弱訊號放大、濾掉雜訊，ADC 轉成數字，MCU 算出數值後顯示在醫療級電腦上，再上傳醫院資訊系統，由醫師或 AI 協助判讀。"],
["關鍵名詞", "醫材分級：風險越高審查越嚴。AFE：類比前端，處理感測器的微弱訊號。遠距醫療：在家量測、資料傳給醫院。PACS：醫學影像儲存與傳輸系統。AI 輔助判讀：用模型幫忙找出影像或訊號中的異常。"],
["景氣看什麼", "人口老化與居家照護需求、醫院設備更新預算、新產品取得各國認證的進度、海外代工訂單與自有品牌通路拓展，以及新台幣匯率變化。"],
["台灣角色", "台灣把電子與資通訊實力用在醫材上，強在居家監測設備、呼吸治療設備、醫療電腦、影像軟體與代工製造，許多產品外銷歐美。"],
],
trends: [
"居家監測設備連網化，量測資料直接上傳雲端，支援遠距醫療與慢性病管理",
"AI 輔助判讀導入醫學影像與生理訊號，協助醫師篩檢與排序急診病人",
"超音波等影像設備走向手持化與低價化，從醫院擴散到診所與居家",
"醫院資訊系統上雲，影像與病歷跨院共享，帶動資安與系統整合需求",
],
