how: [
["在做什麼", "很多疾病的判斷要靠檢驗數字，例如血糖、發炎指標、病毒感染。體外診斷就是把檢體拿到體外，用試劑與儀器把身體狀況變成看得懂的數據。"],
["怎麼運作", "血糖試片上的酵素和血中葡萄糖反應，電極量到的電流大小換算成血糖值；快篩試紙上的抗體金顆粒抓住目標蛋白，隨液體流到 T 線被攔下顯色；PCR 則反覆升降溫，讓目標基因片段每輪加倍，螢光訊號越早上升代表含量越多。"],
["關鍵名詞", "POCT：在床邊或家裡就能快速檢測。免疫檢測：用抗體抓出特定蛋白。PCR：把基因片段放大後偵測，靈敏度高。C 線：控制線，沒出現代表試紙無效。試劑耗材：儀器賣出後持續帶來的收入。"],
["景氣看什麼", "糖尿病等慢性病人口、試片與試劑的長期訂單、各國醫療保險給付、新檢測項目取證；疫情期間快篩需求暴增後回落的循環也要留意。"],
["台灣角色", "台灣在血糖儀與試片代工、居家檢測設備有不少廠商，也有公司發展分子診斷平台；常見模式是替國際品牌代工，或在新興市場經營自有品牌。"],
],
trends: [
"血糖監測由指尖採血試片，逐步轉向貼在皮膚上的連續血糖監測",
"分子檢測儀器小型化，PCR 從中央實驗室走到診所與床邊",
"檢驗科導入全自動化產線，同一台儀器處理生化與免疫等多種項目",
"居家自我檢測普及，檢測結果連到手機與雲端，方便醫師追蹤",
],
