how: [
["在做什麼", "新藥公司找出致病的關鍵標靶，設計出能作用在它身上的藥物，例如抓住細胞表面受體的抗體藥，或能鑽進細胞的小分子藥，再一步步用實驗證明安全又有效。再生醫療則是用病人自己或他人的細胞，經培養處理後拿來修復或治療。"],
["怎麼運作", "先在實驗室與動物身上測試（臨床前），再進入人體臨床：一期看安全、二期看療效與劑量、三期用大量病人確認，每一關都會淘汰大量候選藥。通過主管機關審查後才能上市；很多公司在二期前後就授權給國際大藥廠。抗體藥要在生物反應槽裡用細胞生產、再純化。"],
["關鍵名詞", "授權（License-out）：把藥的權利賣給大藥廠換取簽約金與里程碑金。解盲：揭曉臨床試驗哪組用藥、看是否達標。CDMO：受託開發與製造。孤兒藥：罕見疾病用藥，常有審查與市場獨占優惠。"],
["景氣看什麼", "臨床試驗解盲結果、主管機關審查時程、授權合約、已上市藥品的銷售成長、CDMO 訂單與產能利用率；利率與資金環境也會影響研發型公司的募資難易。"],
["台灣角色", "台灣多數新藥公司規模較小，常走「研發到某階段後授權」或專攻特定適應症；也有公司以 CDMO、學名藥或細胞治療服務建立穩定營收。"],
],
trends: [
"藥物型態從小分子擴展到抗體、抗體藥物複合體與細胞基因治療",
"大藥廠專利到期壓力大，持續向中小型生技公司授權或併購新藥",
"國際藥廠分散生產基地，生物藥 CDMO 產能往亞洲擴張",
"再生醫療法規逐步建立，細胞治療從特管辦法走向正式的產品審查",
],
