how: [
["在做什麼", "全世界大部分的商品都裝在標準尺寸的鐵貨櫃裡，用巨大的貨櫃輪跨洋運送。航商賺的是「運費」，運一個貨櫃收多少錢，是影響獲利最大的關鍵。"],
["怎麼運作", "工廠把貨裝櫃，拖車拉到港口堆場，岸橋把貨櫃吊上船；貨櫃輪沿固定航線依序停靠各港，到目的港卸櫃後，再由卡車或鐵路送到物流園區與賣場。航商之間常組成聯盟、共用船位。"],
["關鍵名詞", "TEU：一個 20 呎標準貨櫃。運價指數（如上海出口貨櫃運價指數 SCFI）：看運價走勢。長約與現貨：長約價較穩，現貨價波動大。繞航：航道受阻改走遠路，等於吃掉船位。"],
["景氣看什麼", "歐美消費與零售庫存、運價指數走勢、新船交付量、塞港或航道受阻事件、燃油價格與減碳法規，以及各國關稅政策帶來的搶運或觀望。"],
["台灣角色", "台灣有多家全球前段班的貨櫃航商，經營遠洋與亞洲區域航線，獲利隨運價大起大落、股利也跟著變動；另有貨櫃場站、碼頭與港口物流業者支援。"],
],
trends: [
"航商把收入從單純運費延伸到碼頭、場站與端到端物流，降低運價循環對獲利的衝擊",
"減碳法規推動雙燃料新船（LNG、甲醇），新舊船隊的燃油成本差距會拉大",
"地緣政治與航道受阻讓繞航常態化，實際可用船位比帳面運力更重要",
"供應鏈分散到東南亞、印度與墨西哥，航線版圖由跨太平洋集中轉向多點分布",
],
