how: [
["在做什麼", "航空公司把飛機當作「會飛的座位與貨艙」來經營：上層客艙賣機票載客，下層腹艙或專用貨機載貨。飛機很貴、固定成本高，所以坐滿率非常重要。"],
["怎麼運作", "航空公司買或租飛機、規劃航線與航班，透過官網與旅行社賣票；收入扣掉燃油、飛機折舊租金、機組人員薪資、機場費與維修後就是獲利。飛機要定期進廠檢修，衍生出維修 MRO 產業。"],
["關鍵名詞", "載客率：座位被坐滿的比例。收益率：每位乘客每公里貢獻的收入。腹艙：客機下方載貨的空間。燃油避險：預先鎖定油價。MRO：維修、修理與大修。"],
["景氣看什麼", "出國旅遊與商務需求、航空貨運（電子產品急單）運價、國際油價、美元匯率（飛機與油多以美元計價）、新機交付進度與航權開放。"],
["台灣角色", "台灣有兩大傳統航空與新興航空公司，經營亞洲、北美與歐洲航線；也有具規模的飛機維修廠替國內外航空公司服務，航太零組件廠則供應國際飛機製造商。"],
],
trends: [
"飛機製造商交機延遲，航空公司延長舊機服役，帶動維修與零件更換需求",
"永續航空燃油（SAF）摻混逐步納入法規，燃油成本結構會跟著改變",
"AI 伺服器等高價電子品急單帶動航空貨運，客機腹艙與貨機收入比重提高",
"新一代省油機型陸續換裝，機隊年輕化成為降低單位成本的關鍵",
],
