how: [
["在做什麼", "物流就是把東西從出貨地準時、安全地送到收件人手上。國際物流承攬業者像「貨運旅行社」，幫客戶找艙位、處理文件報關，再串起運輸、倉儲與配送。"],
["怎麼運作", "貨主把貨交給承攬業者，業者向航空或航運公司訂艙並報關；貨物以空運（快、貴）或海運（慢、便宜）送達後，進倉儲中心用輸送帶分揀、上架暫存，最後由卡車或宅配送到門口。"],
["關鍵名詞", "承攬（Forwarder）：自己不一定有運具，負責整合安排。保稅倉：貨物暫存時先不課關稅。最後一哩：送到收件人手上的最後一段。冷鏈：全程低溫運送。"],
["景氣看什麼", "進出口貿易量、空運與海運運價、電子產品與 AI 伺服器的急單空運需求、電商與跨境包裹量、油價與司機人力成本。"],
["台灣角色", "台灣出口以電子產品為主，國際承攬業者跟著電子供應鏈到海外設點服務客戶；國內則有陸運、倉儲、宅配、貨櫃場站與港區物流業者。"],
],
trends: [
"電子供應鏈移往東南亞、墨西哥與美國，承攬業者跟著客戶在新生產基地設點",
"AI 伺服器體積大、單價高，需要專門的包裝、溫控與保全運送，服務單價較高",
"倉儲導入自動分揀、機器人揀貨與倉儲管理系統，降低對人力的依賴",
"跨境電商包裹與冷鏈（生鮮、醫藥）成為物流業者的新成長來源",
],
