how: [
["在做什麼", "建商買下土地，規劃蓋住宅或商辦，賣給購屋者賺取價差；也有公司持有商場、辦公室或參與都更，靠收租與資產增值賺錢。"],
["怎麼運作", "取得土地後申請建照，通常先「預售」收訂金與工程款，再發包營造廠打地基、蓋地下室、逐層灌漿，興建 2～4 年，完工交屋時才一次認列營收與獲利。所以建商營收常集中在交屋那幾季。"],
["關鍵名詞", "預售屋：蓋好之前先賣。完工交屋認列：交屋才算營收。合約負債：已收但還沒能認列的預收款。土建融：土地與建築融資。都更：舊建物重建。"],
["景氣看什麼", "房貸利率與央行信用管制、預售市場買氣與房價、土地取得成本、營造人力與建材價格、各建案的完工交屋時程與合約負債變化。"],
["台灣角色", "台股有許多上市櫃建商與營造廠，營運高度受國內房市政策與利率影響；水泥、鋼筋等建材業者則跟著營建景氣起伏，部分建商也投入商辦、都更與長期收租。"],
],
trends: [
"央行信用管制與限貸政策讓住宅買氣降溫，建商更重視手上合約負債的交屋進度",
"營造缺工使工期拉長，預鑄工法與鋼構等工業化營建受到重視",
"都市更新與危老重建成為都會區取得建地的主要方式",
"建商從賣屋一次性獲利轉向商辦、廠辦與長期收租，追求穩定現金流",
],
