how: [
["在做什麼", "銀行是資金的「中間人」：把大家存進來的錢，借給需要買房、做生意的人或企業。它賺的主要是存放款之間的利息差，再加上各種金融服務的手續費。"],
["怎麼運作", "銀行付較低的利息吸收存款（負債），再以較高的利率放款、買債券（資產）；資產減負債就是股東的淨值。財富管理、信用卡、匯款等服務收取手續費。借款人若還不出錢，銀行要提列呆帳損失。"],
["關鍵名詞", "NIM（淨利差）：放款收益與資金成本的差距。逾放比：還不出錢的放款比例。備抵呆帳：預先準備的損失準備。金控：旗下同時有銀行、保險、證券等子公司。"],
["景氣看什麼", "央行利率方向、放款成長（特別是房貸與企業貸款）、逾放比與呆帳變化、財富管理手續費、股債市場對投資收益的影響、現金股利政策。"],
["台灣角色", "台股金融股多以「金控」形式掛牌，包含公股與民營體系，常被視為穩定配息的族群；經營重點在國內放款、財富管理與海外分行布局。"],
],
trends: [
"財富管理與信用卡等手續費收入比重提升，降低對利差的依賴",
"台商供應鏈外移帶動海外分行與聯貸業務，跟著客戶到東南亞與美國",
"數位帳戶、行動支付與 AI 風控普及，銀行比拚的是數位流量與資料能力",
"金控之間整併與資本適足要求提高，規模與資本實力影響配息能力",
],
