how: [
["在做什麼", "保險是把風險「分攤」出去：很多人各繳一點保費，少數人發生事故時由保險公司理賠。保險公司先收錢、後理賠，中間這筆長期資金就是投資的本錢。"],
["怎麼運作", "保險公司透過業務員與銀行通路賣保單，收保費後提存準備金，資金投資在債券、股票與海外資產；發生事故時理賠給保戶。遇到地震、颱風等可能造成巨額理賠的風險，會把一部分分給再保公司承擔。"],
["關鍵名詞", "準備金：為未來理賠預留的錢。再保險：保險公司向再保公司投保。綜合率：產險理賠加費用占保費的比例，低於 100% 才有承保利潤。IFRS 17：新的保險會計制度。避險成本：海外投資規避匯率風險的花費。"],
["景氣看什麼", "長短期利率（影響投資收益與保單成本）、股債市場表現、新台幣匯率與避險成本、天災理賠、保單銷售與法規資本要求。"],
["台灣角色", "台灣壽險業資產龐大、海外投資比重高，獲利受利率與匯率影響大，多以金控形式掛牌；產險與再保公司規模較小，獲利看理賠控管與天災。"],
],
trends: [
"IFRS 17 與新一代清償能力制度上路，保險公司更重視資本與負債的配置",
"保單從儲蓄型轉向保障型、外幣與投資型商品，降低長期保證利率的壓力",
"極端氣候讓巨災理賠變多，再保費率與自留風險的拿捏更重要",
"壽險業調整海外債券的匯率避險方式，匯率波動對獲利的影響仍大",
],
