how: [
["在做什麼", "半導體與電子製造會用掉大量的酸、溶劑、貴金屬與晶圓，用過後如果直接丟棄既污染又浪費。回收產業把這些廢料變回可再用的材料，降低成本，也幫客戶達成減碳與環保要求。"],
["怎麼運作", "回收業者到工廠收集廢液、舊靶材、用過的控擋片，分類後走不同製程：含銅廢液用電解把銅析出，貴金屬經熔煉與化學精煉純化，控擋片研磨拋光變成再生晶圓，再生料再賣回產線；無法回收的殘渣送最終處理。"],
["關鍵名詞", "循環經濟：資源用完再回到生產端。再生晶圓：把控片、擋片磨掉表面重複使用。靶材：濺鍍用的金屬塊，用剩的部分可回收。電解：通電讓溶液中的金屬析出在電極上。"],
["景氣看什麼", "晶圓廠產能利用率與擴廠（廢料量跟著增加）、金銀銅等金屬價格、環保法規與客戶的再生料使用目標、新回收廠的建置進度。"],
["台灣角色", "台灣晶圓廠密集，讓在地回收業者有穩定料源；業者涵蓋金屬與廢液回收、貴金屬精煉、再生晶圓與廢棄物處理，越來越被視為半導體供應鏈的一環。"],
],
trends: [
"晶圓廠把再生料使用比例列入供應商要求，回收從處理成本變成材料來源",
"先進製程用到更多稀有金屬與特殊化學品，高純度再生的技術門檻提高",
"回收廠跟著晶圓廠擴廠就近設點，形成在地的循環材料聚落",
"碳費與循環經濟法規上路，回收再生料的減碳效益可以計入客戶的碳盤查",
],
