how: [
["在做什麼", "把處理器、記憶體、面板、電池等零件組裝成筆電、桌機與平板，賣給一般消費者、學生與企業。PC 已是成熟市場，成長主要來自換機潮與新功能。"],
["怎麼運作", "品牌廠決定產品規格、價格與行銷，委託 ODM 代工廠設計與生產；代工廠向各零組件廠採購後組裝、測試，出貨給品牌，再經電商、量販與經銷商賣到用戶手上。"],
["關鍵零件", "處理器 SoC（CPU、GPU、NPU 整合在一起，決定效能）、記憶體與固態硬碟、面板、電池模組、鍵盤、風扇與熱導管、機殼與轉軸。AI PC 內建 NPU，可在本機執行 AI 功能。"],
["景氣看什麼", "作業系統更新帶動的企業換機、AI PC 滲透率、開學與年底購物旺季、通路庫存水位、記憶體與面板價格、關稅與生產基地轉移。"],
["台灣角色", "全球多數筆電由台灣 ODM 代工，台灣也有國際級 PC 品牌，以及電池、轉軸、鍵盤、散熱、機殼等零組件廠，是 PC 供應鏈的核心。"],
],
trends: [
"AI PC 內建 NPU 成為新規格，處理器從 x86 擴展到 Arm 架構，競爭者變多",
"生產基地由中國分散到越南、泰國、墨西哥等地，ODM 多地生產成為常態",
"輕薄機身塞進更高效能，散熱、轉軸與電池模組的設計難度與單價提高",
"企業換機以作業系統世代更替為主要驅動，消費市場則看新功能與價格帶",
],
