desc: "AI 代理（Agent）會把任務拆成很多步驟：查資料、執行程式、呼叫工具，再請 GPU 跑模型推論。這些調度與工具工作多由 CPU 負責，讓資料中心的 CPU 需求重新受到重視。",
flow: ["使用者任務", "CPU 拆解與調度", "GPU 模型推論", "CPU 執行工具與程式", "回傳結果"],
