how: [
["在做什麼", "一般晶片出廠後電路就固定了，FPGA 卻能用設定檔重新設定內部連線，變成不同功能的電路。邊緣 AI 則是在裝置本身跑 AI，讓攝影機、車子、機器能當場判斷，不用等雲端回覆。"],
["怎麼運作", "FPGA 內部有大量邏輯區塊、DSP 運算單元與記憶體，中間用可程式的連線與開關串接；工程師用 EDA 軟體完成設計後燒錄進去，就能得到客製化的硬體。邊緣裝置則用 FPGA、NPU 或專用 AI 晶片，在本機對感測資料即時推論並做出動作。"],
["關鍵名詞", "FPGA：現場可程式邏輯閘陣列。ASIC：為特定用途量身打造、出廠就固定的晶片。原型驗證：先用 FPGA 模擬 ASIC 設計。DSP：做乘加運算的單元，適合訊號處理與 AI。NPU：專門做 AI 推論的處理單元。"],
["景氣看什麼", "通訊基地台、工業與車用市場的庫存循環，國防航太訂單，AI 晶片開發帶動的原型驗證需求，以及智慧攝影機、車用 ADAS 等邊緣 AI 裝置的出貨量。"],
["代表公司", "FPGA 有 AMD（收購 Xilinx）、Lattice、Microchip，Altera 已從 Intel 分拆；邊緣 AI 晶片有 Qualcomm、Ambarella、NXP 等；EDA 業者提供 FPGA 原型驗證系統。"],
],
trends: [
"FPGA 加入 AI 引擎與更多 DSP 單元，往「自適應運算」平台發展",
"AI 晶片設計越來越大，用多顆 FPGA 組成原型驗證系統的需求提高",
"邊緣 AI 從攝影機擴展到機器人、工業視覺與車用，強調低功耗與即時性",
"低功耗小型 FPGA 進入伺服器管理、安全啟動等控制功能",
],
