how: [
["在做什麼", "一般電腦用 0 或 1 計算，量子電腦用「量子位元」，可以同時處在多種狀態的疊加，適合模擬分子、材料或找最佳解這類傳統電腦要算非常久的問題。"],
["怎麼運作", "超導路線的量子位元晶片放在稀釋冷凍機最底層，一層層降到接近絕對零度；外面的控制電子把微波脈衝經過衰減器送進去操作位元，讀出訊號再經放大器傳出來，交給古典電腦與 GPU 解碼。另有離子阱、光子、中性原子與量子退火等路線。"],
["關鍵名詞", "量子位元（qubit）：計算的基本單位。退相干：量子狀態被雜訊破壞。錯誤更正：用很多實體位元組成一個穩定的「邏輯位元」，是能否實用的關鍵。稀釋冷凍機：把晶片降到毫開爾文等級的低溫設備。"],
["景氣看什麼", "邏輯位元數量與錯誤率的進展、政府與大企業的研發預算、雲端量子服務的使用量；目前多數公司仍在虧損、靠募資推進，股價隨技術消息大幅波動。"],
["代表公司", "IBM、Google、Rigetti 走超導路線，IonQ 與 Honeywell 持有的 Quantinuum 走離子阱，D-Wave 做量子退火；輝達提供 GPU 混合運算平台，亞馬遜、微軟提供雲端量子服務。台灣仍以學研機構研發為主。"],
],
trends: [
"研發重點由增加實體位元數量，轉向降低錯誤率、做出能長時間運算的邏輯位元",
"量子電腦和 GPU 超級電腦混合運算，由古典電腦即時解碼錯誤並分擔部分計算",
"超導、離子阱、中性原子、光子多條路線並行競爭，尚未出現勝出的標準架構",
"各國推動後量子密碼，提前替換未來可能被量子電腦破解的加密方式",
],
