how: [
["在做什麼", "大企業的系統往往新舊混雜，自己沒有足夠工程師。IT 服務公司幫忙規劃要怎麼改、把 ERP、CRM、雲端、資料和 AI 串在一起，之後再接手長期維運。"],
["怎麼運作", "專案從顧問規劃、系統設計開始，建置整合期投入最多人力，上線後常轉成多年委外維運合約。整合層用 API 把舊主機和新系統接起來；少數顧問在客戶端，大量工程師放在印度、東歐等成本較低的離岸交付中心。"],
["關鍵名詞", "系統整合（SI）：把不同廠商的系統接起來。委外（outsourcing）：把 IT 工作整包交給外部公司。人天計價與固定總價：兩種收費方式。簽約金額（bookings）：未來營收的領先指標。"],
["景氣看什麼", "企業是否願意花錢做轉型專案、新簽約金額、員工使用率與人力成本、匯率；也要留意 AI 寫程式工具是否會減少按人力計價的工作量，或反過來帶來新的 AI 導入專案。"],
["代表公司", "Accenture、IBM 偏顧問與大型整合，Cognizant、Infosys、Wipro 偏離岸委外與維運，EPAM、Globant 做軟體開發外包，Booz Allen、Leidos 服務美國政府。台灣的系統整合商規模較小，多服務本地企業與政府。"],
],
trends: [
"企業導入生成式 AI 需要整合資料與流程，帶來新的顧問與系統整合專案",
"AI 寫程式工具提高工程師產能，收費方式由按人力計價轉向按成果或固定總價",
"大型專案集中在雲端遷移、ERP 升級與資料平台，IT 服務商與軟體平台深度合作",
"交付中心持續往成本較低的地區分散，同時保留少數高階顧問在客戶當地",
],
