how: [
["在做什麼", "交易所是買賣雙方見面的市場，負責把買單和賣單配對成交；它和指數、評級公司也把市場上產生的報價、指數和信用資訊包裝成資料產品，賣給基金和銀行。"],
["怎麼運作", "投資人透過券商下單，交易所的撮合引擎依「價格優先、時間優先」把最高買價與最低賣價配對成交；成交後由結算所站在買賣雙方中間，收保證金並確保錢和股票（或期貨部位）真的交割。過程中產生的即時報價、成交資料再賣給各金融機構。"],
["關鍵名詞", "撮合：把買賣單配對。買賣價差：最高買價與最低賣價的差距。結算所：站在買賣中間保證交割。造市商：持續掛出買賣報價提供流動性。指數授權：ETF 追蹤某個指數就要付費給指數公司。信用評級：替公司與債券的違約風險打分數。"],
["景氣看什麼", "市場成交量與波動度（波動大時交易多）、利率期貨等避險需求、ETF 資產規模（影響指數授權費）、企業發債量（影響評級收入），以及資料訂閱的續約與漲價。"],
["代表公司", "洲際交易所（旗下紐約證交所）、CME（期貨）、Nasdaq、Cboe（選擇權）；標普全球、穆迪、MSCI 做指數與評級，FactSet 做金融資料；嘉信、Robinhood、盈透是券商，Virtu 是造市商。台灣對應的是臺灣證交所與期交所。"],
],
trends: [
"交易所收入由交易手續費轉向資料、指數授權與軟體等經常性收入",
"散戶選擇權交易熱絡，短天期合約的成交量明顯放大",
"交易所延長交易時段、朝 24 小時交易發展，並推出代幣化資產等新商品",
"主動式與被動式 ETF 持續成長，指數公司的授權收入跟著資產規模增加",
],
