how: [
["在做什麼", "退休基金、保險公司和有錢人想找股票、公債以外的投資。另類資產管理公司替他們成立基金，去買未上市公司、直接放款給企業、買不動產和資料中心等基礎建設。"],
["怎麼運作", "管理公司（GP）向出資人（LP）募資成立基金，資金常鎖定好幾年；投資後慢慢改善公司、收租或收利息，最後賣出或到期回收。回收的錢先還出資人本金和約定的保底報酬，超額獲利再由 GP 抽績效分成；另外 GP 每年也收管理費。"],
["關鍵名詞", "私募股權：買下或入股未上市公司。私募信貸：不透過銀行、直接借錢給企業。AUM：管理資產規模。永續資本：保險資金等不用定期還給出資人的長期資金。BDC：在股市掛牌、專門放款給中型企業的投資公司。"],
["景氣看什麼", "募資速度與 AUM 成長、利率（影響信貸收益與資產估值）、併購與 IPO 市場是否熱絡（決定能不能順利退出）、私募信貸的違約率，以及資料中心與電力基礎建設的融資需求。"],
["代表公司", "Blackstone、KKR、Apollo、Ares、Carlyle、Brookfield、Blue Owl 是代表業者；Apollo 旗下 Athene、KKR 旗下 Global Atlantic 提供保險資金；Ares Capital、Blue Owl Capital Corp 是上市 BDC。台灣的壽險公司與退休基金也是這類基金常見的出資人。"],
],
