how: [
["在做什麼", "你刷卡或用手機付款時，錢要從你的銀行帳戶安全地移到商店手上。支付產業提供這條「金流高速公路」，每經過一筆交易就收一點過路費。"],
["怎麼運作", "商店的刷卡機或網店把交易送給收單機構，再經 Visa、Mastercard 等卡組織的網路傳到你的發卡銀行，銀行確認額度後核准，幾秒內傳回；之後幾天再完成實際的資金清算，把錢撥給商店。商店付的手續費大部分是給發卡行的交換費，卡組織收網路費，收單機構賺加價。"],
["關鍵名詞", "發卡行：發信用卡給你的銀行。收單機構：幫商店收款的業者。交換費：商店手續費中付給發卡行的部分。代碼化（token）：手機錢包用代碼取代真實卡號。先買後付（BNPL）：把一筆消費分期、通常免息。"],
["景氣看什麼", "消費支出與通膨、跨境旅遊交易量（手續費較高）、現金轉數位的速度、各國對手續費的監管，以及即時轉帳、穩定幣等新支付方式的競爭。"],
["代表公司", "Visa、Mastercard、American Express 是卡組織；Global Payments、PayPal 做收單與線上金流，Block（Square）、Toast 做商家收款系統；摩根大通、Capital One 是大型發卡行；Apple Pay、PayPal、Cash App 是錢包，Affirm、Klarna 做先買後付。"],
],
trends: [
"手機錢包與代碼化支付普及，實體卡號逐漸被裝置裡的代碼取代",
"跨境電商與旅遊帶動跨境交易，這類交易手續費較高，是卡組織的成長來源",
"即時轉帳與穩定幣興起，卡組織與金流業者也開始支援這些新支付通道",
"收款系統整合點餐、庫存、薪資與貸款，金流業者從收手續費延伸到軟體訂閱",
],
