how: [
["在做什麼", "美國人買房幾乎都靠 30 年期房貸，房市是美國經濟很重要的引擎：一間房子成交，會帶動建材、裝潢、家具家電、房貸與搬家等一連串消費。"],
["怎麼運作", "房貸利率大致跟著 10 年期公債殖利率走。利率高時月付金變重，很多人買不起或不想賣掉手上低利房貸的舊房，成屋交易變少；建商則用補貼利率等方式推新屋，開工量隨需求調整。"],
["關鍵名詞", "新屋開工：建商開始動工的數量，是景氣領先指標。成屋銷售：中古屋成交量。庫存月數：以目前速度要幾個月才能賣完待售房屋。鎖定效應：屋主不想放棄低利房貸。"],
["景氣看什麼", "房貸利率與聯準會政策、就業與薪資、新屋開工與營建許可、成屋庫存與房價；房市回溫時，建材與居家修繕零售通常跟著受惠。"],
["代表公司", "建商有 D.R. Horton、Lennar、PulteGroup、NVR；居家修繕零售有 Home Depot、Lowe's；房貸與平台有 Rocket、Zillow。台灣的五金、手工具、家具與家電出口廠也受美國房市影響。"],
],
trends: [
"屋主捨不得放棄過去的低利房貸，成屋供給偏少，新屋在整體成交中的比重提高",
"建商用補貼房貸利率、蓋較小坪數的房子來維持買方的負擔能力",
"屋齡老化讓修繕與翻新需求相對穩定，專業包商客群成為修繕零售的成長重點",
"買房、貸款、仲介流程持續數位化，房產平台與房貸業者走向一站式服務",
],
