how: [
["在做什麼", "把地底的石油和天然氣開採出來，運送、加工成汽油、柴油、航空燃油和塑化原料，或拿天然氣去發電、液化出口。這是全球最大的能源來源之一。"],
["怎麼運作", "上游公司鑽井開採（美國主要是頁岩，先垂直鑽下去再水平鑽進岩層，用高壓水壓裂讓油氣流出），中游用管線與儲槽運送，下游煉油廠把原油分餾成各種油品。天然氣則透過管線送到發電廠，或冷卻成液化天然氣（LNG）用船出口。"],
["關鍵名詞", "上中下游：開採、運輸、加工。頁岩油氣：從頁岩層開採的油氣。OPEC+：主要產油國聯盟，會調整產量影響油價。LNG：液化天然氣，方便長途海運。煉油價差：油品售價減原油成本。"],
["景氣看什麼", "國際油價與天然氣價、OPEC+ 產量政策、美國鑽井數與庫存、煉油價差；AI 資料中心用電增加，讓天然氣發電需求受到關注。"],
["代表公司", "ExxonMobil、Chevron 是整合型大廠，ConocoPhillips、EOG 偏上游，EQT 產天然氣，Kinder Morgan 經營管線，Cheniere 出口 LNG，SLB 提供油田服務。台灣的台塑化、中油與 LNG 進口都和國際油氣價格相關。"],
],
trends: [
"頁岩業者整併成大型公司，重視現金回饋與資本紀律，不再一味追求增產",
"美國 LNG 出口設施持續擴建，天然氣從內需商品變成全球貿易商品",
"AI 資料中心用電需求帶動燃氣發電，天然氣被視為銜接再生能源的穩定電力",
"油田服務導入自動化鑽井與數據分析，以更少的井數維持產量",
],
