how: [
["在做什麼", "製造蓋路挖地的營建機械、礦場用的大型卡車、農夫用的曳引機與收割機，以及卡車引擎、柴油發電機組和燃氣渦輪等大型設備。"],
["怎麼運作", "引擎帶動液壓泵，高壓油推動液壓缸，讓動臂、鏟斗做出大力氣的動作。政府基建、礦業公司、農民與電力業者下單，機械廠組裝後透過各地經銷商銷售與維修；機器動輒用十幾年，期間不斷更換零件與保養。"],
["關鍵名詞", "經銷商網路：負責銷售、租賃與維修的在地夥伴。售後市場：零件與服務。積壓訂單（backlog）：已接但還沒交貨的訂單。發電機組：資料中心的備用電源。"],
["景氣看什麼", "基建法案與政府預算、銅鐵等商品價格（影響礦業投資）、農產品價格與農民收入、利率、經銷商庫存，以及資料中心帶來的發電設備訂單。"],
["代表公司", "Caterpillar（營建礦業機械與發電機組）、Deere（農機）、Cummins（引擎）、PACCAR（卡車）、GE Vernova（燃氣渦輪），以及設備租賃商 United Rentals。台灣有供應零件、液壓件與鑄件的廠商。"],
],
