how: [
["在做什麼", "銅箔是一層比頭髮還薄的銅片，貼在玻纖布與樹脂上做成銅箔基板（CCL），再蝕刻成印刷電路板上的線路。訊號和電流都靠它傳遞。"],
["怎麼運作", "把銅溶成電解液，通電後銅會在旋轉的鈦滾筒上析出成連續的薄片，剝下來後做表面處理（粗化、防鏽）再捲起。另一種壓延銅箔則是把銅塊反覆輾薄，柔軟耐彎折，多用在軟板。"],
["關鍵名詞", "HVLP：超低輪廓銅箔，表面極平滑，用於高速板。集膚效應：高頻訊號只走在導體表面，所以表面粗糙會增加損耗。極薄銅箔：附載體的超薄銅箔，用於 IC 載板細線路。"],
["景氣看什麼", "AI 伺服器與 800G／1.6T 交換器出貨（帶動高階 CCL）、高階銅箔的產能與加工費、銅價、IC 載板需求；一般消費電子用銅箔則競爭激烈。"],
["和台灣的關係", "台灣的台光電、聯茂、台燿等 CCL 廠是高階銅箔的主要買家，金居等台廠也生產高階銅箔；日本廠在載板用極薄銅箔等領域較具優勢。"],
],
trends: [
"AI 伺服器與高速交換器的傳輸速度提高，HVLP 銅箔一代比一代平滑，規格持續升級",
"高階銅箔產能擴充慢、認證時間長，加工費比一般銅箔更有支撐",
"IC 載板線路越來越細，帶動附載體極薄銅箔需求",
"CCL 廠與銅箔廠更早共同開發材料，銅箔、樹脂與玻纖布要一起搭配調整",
],
