how: [
["在做什麼", "韓國電子元件廠生產三類關鍵零件：調節電流的 MLCC 積層陶瓷電容、承載晶片的 IC 封裝載板，以及手機與汽車用的相機模組，主要客戶是全球手機品牌、伺服器與車廠。"],
["怎麼運作", "MLCC 把陶瓷薄片印上電極、疊上數百層再燒結；FC-BGA 載板用 ABF 增層膜做出細線路，連接晶片和主機板；相機模組把鏡頭、感測器與對焦馬達組裝在一起；AI 伺服器則用層數很高的多層板。"],
["關鍵名詞", "MLCC：最常見的被動元件，一支手機用上千顆。FC-BGA：高階處理器用的封裝載板。ABF：日本味之素開發的增層絕緣膜。多層板：AI 伺服器與交換器用、層數很高的 PCB。車規：汽車用、要求更嚴格的品質等級。"],
["景氣看什麼", "手機新機出貨、AI 伺服器與 AI 晶片的載板需求、車用電子比重、MLCC 庫存與報價，以及韓元匯率。"],
["和台灣的關係", "MLCC 對手是台灣國巨、華新科與日本村田；載板對手是欣興、南電、景碩；相機鏡頭則有大立光、玉晶光。看韓國廠的財報與展望，可以推估同業景氣。"],
],
trends: [
"AI 伺服器用的 MLCC 需要更高容值與耐溫，高階規格比重提升",
"AI 晶片封裝越做越大，FC-BGA 載板層數與面積增加，並評估玻璃基板等新材料",
"相機模組從手機延伸到車用與機器人，車用鏡頭與感測模組比重提高",
"AI 伺服器與交換器的多層板層數更高，帶動高階 PCB 與材料規格升級",
],
