    how: [
      ["在做什麼", "做軍用與政府用的無人機，負責偵察、監視、運補，甚至攻擊；而且關鍵零件要避開中國供應鏈。"],
      ["怎麼運作", "飛控板上的 IMU 感測姿態、GPS 定位，MCU 每秒計算很多次，透過電調調整每顆馬達轉速，讓無人機穩定飛行；光學雲台拍下影像，經資料鏈即時傳回地面站，操作員再下指令。"],
      ["關鍵零件", "飛控板（MCU、IMU、GPS）、無刷馬達與電調、鋰電池、碳纖維機體、EO／IR 光學雲台（白天可見光＋夜間熱影像）、資料鏈與天線、地面站。"],
      ["景氣看什麼", "國防與政府無人機預算、標案實際開出與交貨時程、海外（歐美）訂單、非紅零件的國產化比例與成本。"],
      ["台灣角色", "雷虎、中光電、漢翔做整機與系統，中光電、亞光做光學酬載與鏡頭，台揚、啟碁等做通訊，亞航、長榮航太做維修後勤；政府推動國產無人機與非紅供應鏈。"],
    ],
