    how: [
      ["在做什麼", "把先進封裝的「底盤」從圓形的 12 吋晶圓換成方形大面板，一次能放進更多顆大尺寸 AI 晶片封裝，降低成本、增加產能。"],
      ["怎麼運作", "以玻璃或面板當載體，先用雷射在玻璃上鑽孔（TGV）並填銅，再一層層做重佈線（RDL）細線路，把 GPU 與 HBM 等晶片貼合上去，最後切割成一顆顆封裝，再接到封裝載板。"],
      ["關鍵零件", "玻璃／面板載板、TGV 雷射鑽孔設備、大面積濕製程與曝光設備、壓膜與烘烤設備、晶片貼合設備、檢測設備。"],
      ["景氣看什麼", "台積電等大廠 CoPoS 試產線與量產時程、AI 晶片封裝尺寸放大程度、設備驗證與下單進度、面板翹曲與良率改善情況。"],
      ["台灣角色", "群創把面板廠產線轉做面板級封裝；鈦昇做雷射與 TGV 設備，志聖、群翊做壓膜烘烤，均華做貼合，辛耘做濕製程，跟著晶圓廠與封測廠一起開發。"],
    ],
