    how: [
      ["在做什麼", "沒有司機的計程車：乘客用 App 叫車，車子自己開來、載客、收費，再自己回場站充電整備。"],
      ["怎麼運作", "光達、攝影機、雷達一起感知周圍；車上的自駕電腦用 AI 模型辨識行人車輛、預測動向並決定怎麼開；高精地圖提供車道細節，遇到少見狀況時遠端人員提供協助。L4 代表在劃定的城市區域內完全不需要司機。"],
      ["關鍵零件", "光達（雷射測距畫出 3D 點雲）、多組攝影機、毫米波雷達、自駕運算晶片、訓練 AI 模型用的資料中心，以及叫車派車系統。有些業者主打只用攝影機的純視覺路線。"],
      ["景氣看什麼", "營運城市數與車隊規模、每週付費趟數、每公里成本能否低於有司機的計程車、事故與監管審查；中美業者也在中東、歐洲搶市場。"],
      ["台灣供應鏈關聯", "自駕晶片多由台積電代工，車用鏡頭、雷達模組與電子零件有台廠參與；訓練自駕 AI 模型的伺服器也由台灣代工廠組裝。"],
    ],
